comms.text:
@1 וַאֲמַר יְיָ לְאַבְרָם אִיזֵל לָךְ מֵאַרְעָךְ וּמִיַּלָּדוּתָךְ וּמִבֵּית אֲבוּךְ לְאַרְעָא דִּי אַחֲזִנָּךְ:
@2 וְאֶעְבְּדִנָּךְ לְעַם סַגִּי וֶאֱבָרֵכִנָּךְ וַאֲרַבֵּי שְׁמָךְ וּתְהֵא מְבָרֵךְ:
@3 וֶאֱבָרֵךְ מְבָרְכָךְ וּמְלַטְטָךְ אֵילוּט וְיִתְבָּרֲכוּן בְּדִילָךְ כֹּל זַרְעֲיַת אַרְעָא:
@4 וַאֲזַל אַבְרָם כְּמָא דְּמַלֵּיל עִמֵּהּ יְיָ וַאֲזַל עִמֵּהּ לוֹטּ וְאַבְרָם בַּר שִׁבְעִין וַחֲמֵשׁ שְׁנִין בְּמִפְקֵהּ מֵחָרָן:
@5 וּדְבַר אַבְרָם יָת שָׂרַי אִתְּתֵהּ וְיָת לוֹט בַר אֲחוּהִי וְיָת כָּל קִנְיָנְהוֹן דִּי קְנוֹ וְיָת נַפְשָׁתָא דְּשַׁעֲבִּידוּ לְאוֹרַיְתָא בְחָרָן וּנְפָקוּ לְמֵיזַל לְאַרְעָא דִּכְנַעַן וַאֲתוֹ לְאַרְעָא דִּכְנָעַן:
@6 וַעֲבַר אַבְרָם בְּאַרְעָא עַד אֲתַר שְׁכֶם עַד מֵישַׁר מוֹרֶה וּכְנַעֲנָאָה בְּכֵן בְּאַרְעָא:
@7 וְאִתְגְּלִי יְיָ לְאַבְרָם וַאֲמַר לִבְנָךְ אֶתֵּן יָת אַרְעָא הָדָא וּבְנָא תַמָּן מַדְבְּחָא קֳדָם יְיָ דְּאִתְגְּלִי לֵהּ:
@8 וְאִסְתַּלַּק מִתַּמָּן לְטוּרָא מִמַדְנַח לְבֵית אֵל וּפְרַס מַשְׁכְּנֵהּ בֵּית אֵל מִמַּעַרְבָא וְעַי מִמָּדִינְחָא וּבְנָא תַמָּן מִדְבְּחָא קֳדָם יְיָ וְצַלִּי בִּשְׁמָא דַּיְיָ:
@9 וּנְטַּל אַבְרָם אָזֵל וְנָטֵל לְדָרוֹמָא:
@10 וַהֲוָה כַפְנָא בְּאַרְעָא וּנְחַת אַבְרָם לְמִצְרַיִם לְאִתּוֹתָבָא תַמָּן אֲרֵי תַקִּיף כַּפְנָא בְּאַרְעָא:
@11 וַהֲוָה כַּד קְרֵיב לְמֵיעַל לְמִצְרָיִם וַאֲמַר לְשָׂרַי אִתְּתֵה הָא כְעַן יְדָעִית אֲרֵי אִתְּתָא שַׁפִּירַת חֵיזוּ אָתְּ:
@12 וִיהֵי כַּד (נ''י אֲרֵי) יֶחֱזוּן יָתִיךְ מִצְרָאֵי וְיֵימְרוּן אִתְּתֵהּ דָּא וְיִקְטְלוּן יָתִי וְיָתִיךְ יְקַיְמוּן:
@13 אִמְרִי כְעַן אֲחָתִי אָתְּ בְּדִיל דְּיֵיטַב לִי בְּדִילָךְ וְתִתְקַיֵּם נַפְשִׁי בְּפִתְגָּמָיְכִי:
@14 וַהֲוָה כַּד עַל אַבְרָם לְמִצְרָיִם וַחֲזוֹ מִצְרָאֵי יָת אִתְּתָא אֲרֵי שַׁפִּירָא הִיא לַחֲדָא:
@15 וַחֲזוֹ יָתַהּ רַבְרְבֵי פַרְעֹה וְשַׁבָּחוּ יָתַהּ לְפַרְעֹה וְאִדַּבָּרַת אִתְּתָא לְבֵית פַּרְעֹה:
@16 וּלְאַבְרָם אוֹטִיב בְּדִילַהּ וַהֲווֹ לֵהּ עָאן וְתוֹרִין וַחֲמָרִין וְעַבְדִין וְאַמְהָן וְאַתְנָן וְגַמְלִין:
@17 וְאַיְתִי יְיָ עַל פַּרְעֹה מַכְתָּשִׁין רַבְרְבִין וְעַל אֱנַשׁ בֵּיתֵהּ עַל עֵיסַק שָׂרַי אִתַּת אַבְרָם:
@18 וּקְרָא פַרְעֹה לְאַבְרָם וַאֲמַר מָה דָּא עֲבַדְתְּ לִי לְמָא לָא חַוֵּיתָא לִי אֲרֵי אִתְּתָךְ הִיא:
@19 לְמָא אֲמַרְתְּ אֲחָתִי הִיא וּדְבָרִית יָתַהּ לִי לְאִתּוּ וּכְעַן הָא אִתְּתָךְ דְּבַר וְאִיזֵל:
@20 וּפַקִּיד עֲלוֹהִי פַּרְעֹה גּוּבְרִין וְאַלְוִיאוּ יָתֵהּ וְיָת אִתְּתֵהּ וְיָת כָּל דִילֵהּ:
@21 וּסְלֵיק אַבְרָם מִמִּצְרַיִם הוּא וְאִתְּתֵהּ וְכָל דִּילֵהּ וְלוֹט עִמֵּהּ לְדָרוֹמָא:
@22 וְאַבְרָם תַּקִּיף לַחֲדָא בִּבְעִירָא בְּכַסְפָּא וּבְדַהֲבָא:
@23 וַאֲזַל לְמַטְלָנוֹהִי מִדָּרוֹמָא וְעַד בֵּית אֵל עַד אַתְרָא דִּי פְּרַס תַּמָּן מַשְׁכְּנֵהּ בְּקַדְמֵיתָא בֵּין בֵּית אֵל וּבֵין עָי:
@24 לַאֲתַר מַדְבְּחָא דִּי עֲבַד תַּמָּן בְּקַדְמֵיתָא וְצַלֵּי תַמָּן אַבְרָם בִּשְׁמָא דַּיְיָ:
@25 וְאַף לְלוֹט דְּאָזִיל עִם אַבְרָם הֲוָה עָאן וְתוֹרִין וּמַשְׁכְּנִין:
@26 וְלָא סוֹבָרַת יָתְהוֹן אַרְעָא לְמִיתַב כַּחֲדָא אֲרֵי הֲוָה קִנְיָנְהוֹן סַגִּי וְלָא יְכִילוּ לְמִיתַּב כַּחֲדָא:
@27 וַהַוַת מַצוּתָא בֵּין רָעֵי בְּעִירֵה דְאַבְרָם וּבֵין רָעֵי בְּעִירֵה דְלוֹט וּכְנַעֲנָאָה וּפְרִזָאָה בְּכֵן יָתִיב בְּאַרְעָא:
@28 וַאֲמַר אַבְרָם לְלוֹט לָא כְעַן תְּהֵי מַצוּתָא בֵּינָא וּבֵינָךְ וּבֵין רַעֲוָתִי וּבֵין רַעֲוָתָךְ אֲרֵי גוּבְרִין אַחִין אֲנָחְנָא:
@29 הֲלָא כָל אַרְעָא קֳדָמָךְ אִתְפָּרַשׁ כְּעַן מִלְוָתִי אִם אַתְּ לְצִפּוּנָא וַאֲנָא לְדָרוֹמָא וְאִם אַתְּ לְדָרוֹמָא וַאֲנָא לְצִפּוּנָא:
@30 וּזְקַף לוֹט יָת עֵינוֹהִי וַחֲזָא יָת כָּל מֵישַׁר יַרְדְנָא אֲרֵי כֻלַהּ בֵּית שַׁקְיָא קֳדָם חַבָּלוּת יְיָ יָת סְדוֹם וְיָת עֲמֹרָא כְּגִנְתָא דַיְיָ כְּאַרְעָא דְמִצְרַיִם מָטֵּי לְצוֹעַר:
@31 וּבְחַר לֵיהּ לוֹט יַת כָּל מֵישַׁר יַרְדְנָא וּנְטַל לוֹט מִלְקַדְמִין וְאִתַּפְרָשׁוּ גְבַר מִלְוַת אָחוּהִי:
@32 אַבְרָם יָתֵיב בְּאַרְעָא דִכְנָעַן וְלוֹט יָתֵיב בְּקִרְוֵי מֵישְׁרָא וּפְרַס עַד סְדוֹם:
@33 וֶאֱנָשִׁין דִסְדוֹם בִּישִׁין בְּמָמוֹנְהוֹן וְחַיָבִין בִּגְוִיָתְהוֹן קֳדָם יְיָ לַחֲדָא:
@34 וַיְיָ אֲמַר לְאַבְרָם בָּתַר דְאִתְפָּרֶשׁ לוֹט מֵעִמֵהּ זְקוֹף כְּעַן עֵינָךְ וַחֲזֵי מִן אַתְרָא דְאַתְּ תַּמָן לְצִפּוּנָא וּלְדָרוֹמָא וּלְמַדִינְחָא וּלְמַעֲרָבָא:
@35 אֲרֵי יָת כָּל אַרְעָא דִי אַתְּ חָזֵי לָךְ אֶתְּנִנַהּ וְלִבְנָיךְ עַד עָלָם:
@36 וֶאֱשַׁוֵּי יָת בְּנָיךְ סַגִיאִין כְּעַפְרָא דְאַרְעָא כְּמָא דִי לָא אֶפְשַׁר לִגְבַר לְּמִמְנֵי יָת עַפְרָא דְאַרְעָא אַף בְּנָיךְ לָא יִתִּמְנוּן:
@37 קוּם הֲלִיךְ בְּאַרְעָא לְאָרְכַּהּ וְלִפְתָיַהּ אֲרֵי לָךְ אֶתְּנִינַהּ:
@38 וּפְרַס אַבְרָם וַאֲתָא וִיתֵב בְּמֵישְׁרֵי מַמְרֵא דִי בְחֶבְרוֹן וּבְנָא תַמָן מַדְבְּחָא קֳדָם יְיָ:
@39 וַהֲוָה בְיוֹמֵי אַמְרָפֶל מַלְכָּא דְבָבֶל אַרְיוֹךְ מַלְכָּא דְאֶלָסָר כְּדָרְלָעוֹמֶר מַלְכָּא דְעֵילָם וְתִדְעָל מַלְכָּא דְעַמְמֵי:
@40 סְדָרוּ (נ''א עֲבָדוּ) קְרָבָא עִם בֶּרַע מַלְכָּא דִסְדוֹם וְעִם בִּרְשַׁע מַלְכָּא דַעֲמֹרָה שִׁנְאָב מַלְכָּא דְאַדְמָה וְשֶׁמְאֵבֶר מַלְכָּא דִצְבוֹיִם וּמַלְכָּא דְבֶלַּע הִיא צוֹעַר:
@41 כָּל אִלֵין אִתְכְּנָשׁוּ לְמֵישַׁר חַקְלַיָא הוּא אֲתַר יַמָא דְמִלְחָא:
@42 תַּרְתֵּי עַשְׂרֵי שְׁנִין פְּלָחוּ יָת כְּדָרְלָעוֹמֶר וּתְלָת עֶשְׂרֵי שְׁנִין מְרָדוּ:
@43 וּבְאַרְבַּע עֶשְׂרֵי שְׁנִין אֲתָא כְּדָרְלָעֹמֶר וּמַלְכַיָא דְעִמֵהּ וּמְחוֹ יָת גִבָּרַיָא דִי בְעַשְׁתְּרוֹת קַרְנַיִם וְיָת תַּקִיפַיָא דִבְהֶמְתָּא וְיָת אֵמְתָנֵי דִבְשָׁוֵה קִרְיָתָיִם:
@44 וְיָת חוֹרָאֵי דִי בְּטוּרְהוֹן דְשֵׂעִיר עַד מֵישַׁר פָּארָן דִסְמִיךְ עַל מַדְבְּרָא:
@45 וְתָבוּ וַאֲתוּ לְמֵישַׁר פִּלּוּג דִינָא הִיא רְקָם וּמְחוֹ יָת כָּל חֲקַל עֲמַלְקָאָה וְאַף יָת אֱמוֹרָאָה דְיָתֵיב בְּעֵין גֶּדִי:
@46 וּנְפַק מַלְכָּא דִסְדוֹם וּמַלְכָּא דַעֲמוֹרָה וּמַלְכָּא דְאַדְמָה וּמַלְכָּא דִצְבוֹיִם וּמַלְכָּא דְבֶלַע הִיא צוֹעַר וְסַדָרוּ עִמְהוֹן קְרָבָא בְּמֵישַׁר חַקְלַיָא:
@47 עִם כְּדָרְלָעֹמֶר מַלְכָּא דְעֵילָם וְתִדְעָל מַלְכָּא דְעַמְמִין וְאַמְרָפֶל מַלְכָּא דְבָבֶל וְאַרְיוֹךְ מַלְכָּא דְאֶלָסָר אַרְבְּעָה מַלְכִין לָקֳבֵיל חַמְשָׁא:
@48 וּמֵישַׁר חַקְלַיָא בֵּירִין בֵּירִין מַסְקַן חֵימָרָא וַעֲרָקוּ מַלְכָּא דִסְדוֹם וַעֲמוֹרָה וּנְפָלוּ תַמָן וּדְאִשְׁתָּאֲרוּ לְטוּרָא עֲרָקוּ:
@49 וּשְׁבוֹ יָת כָּל קִנְיָנָא דִסְדוֹם וַעֲמוֹרָה וְיָת כָּל מֵיכָלְהוֹן וַאֲזָלוּ:
@50 וּשְׁבוֹ יָת לוֹט וְיָת קִנְיָנֵהּ בַּר אַחוּהִי דְאַבְרָם וַאֲזָלוּ וְהוּא יָתֵיב בִּסְדוֹם:
@51 וַאֲתָא מְשֵׁיזָבָא וְחַוִּי לְאַבְרָם עִבְרָאָה וְהוּא שָׁרֵי בְּמֵישְׁרֵי מַמְרֵא אֱמוֹרָאָה אֲחוּהִי דְאֶשְׁכּוֹל וַאֲחוּהִי דְעָנֵר וְאִינוּן אֱנָשֵׁי קְיָמֵהּ דְאַבְרָם:
@52 וּשְׁמַע אַבְרָם אֲרֵי אִשְׁתְּבִי אֲחוּהִי וְזָרֵיז יָת עוּלֵמוֹהִי יְלִידֵי בֵיתֵהּ תְּלַת מְאָה וְתַמְנֵי עֲסַר וּרְדַף עַד דָן:
@53 וְאִתְפְּלֵג עֲלֵיהוֹן לֵילְיָא הוּא וְעַבְדוֹהִי וּמְחוֹנוּן וּרְדָפִנוּן עַד חוֹבָא דִי מִצִפּוּנָא לְדַמָשֶׂק:
@54 וַאֲתֵיב יָת כָּל קִנְיָנָא וְאַף יָת לוֹט בַּר אֲחוּהִי וְקִנְיָנֵהּ אֲתֵיב וְאַף יָת נְשַׁיָא וְיָת עַמָא:
@55 וּנְפַק מַלְכָּא דִסְדוֹם לְקַדָמוּתֵה בָּתַר דְתָב מִלְמִמְחֵי יָת כְּדָרְלָעוֹמֶר וְיָת מַלְכַיָא דִי עִמֵהּ לְמֵישַׁר מַפְנָא הוּא אֲתַר בֵּית רֵיסָא דְמַלְכָּא:
@56 וּמַלְכִּי צֶדֶק מַלְכָּא דִירוּשְׁלֶם אַפֵּיק לְחֵם וַחֲמָר וְהוּא מְשַׁמֵשׁ קֳדָם אֵל עִלָאָה:
@57 וּבָרְכֵיהּ וַאֲמָר בְּרִיךְ אַבְרָם לְאֵל עִלָאָה דְקִנְיָנֵהּ שְׁמַיָא וְאַרְעָא:
@58 וּבְרִיךְ אֵל עִלָאָה דִמְסַר סָנְאָיךְ בִּידָךְ וִיהַב לֵיהּ חַד מִן עַשְׂרָא מִכֹּלָא:
@59 וַאֲמַר מַלְכָּא דִסְדוֹם לְאַבְרָם הַב לִי נַפְשָׁתָא וְקִנְיָנָא (סַב) דְבַר לָךְ:
@60 וַאֲמַר אַבְרָם לְמַלְכָּא דִסְדוֹם אֲרֵמִית יְדַי בִּצְלוֹ קֳדָם יְיָ אֵל עִלָאָה דְקִנְיָנֵהּ שְׁמַיָא וְאַרְעָא:
@61 אִם מִחוּטָא וְעַד עַרְקַת מְסָנָא וְאִם אֶסַב מִכָּל דִי לָךְ וְלָא תֵימַר אֲנָא אַעְתָּרִית יָת אַבְרָם:
@62 לְחוֹד (בַּר) מִדִאֲכָלוּ עוּלֵמַיָא וְחָלָק גֻבְרַיָא דִי אֲזָלוּ עִמִי עָנֵר אֶשְׁכּוֹל וּמַמְרֵא אִינוּן יְקַבְּלוּן חַלָקְהוֹן:
@63 בָּתַר פִּתְגָמַיָא הָאִלֵין הֲוָה פִּתְגָמָא דַיְיָ עִם אַבְרָם בִּנְבוּאָה לְמֵימָר לָא תִדְחַל אַבְרָם מֵימְרִי תְּקוֹף לָךְ אַגְרָךְ סַגִי לַחֲדָא:
@64 וַאֲמַר אַבְרָם יְיָ אֱלֹהִים מַה תִּתֶּן לִי וַאֲנָא אָזֵיל בְּלָא וְלָד וּבַר פַּרְנָסָא הָדֵין דִבְּבֵיתִי הוּא דַמַשְׂקָאָה אֱלִיעֶזֶר:
@65 וַאֲמַר אַבְרָם הָא לִי לָא יְהַבְתְּ וְלָד וְהָא בַר בֵיתִי יָרִיתּ יָתִי:
@66 וְהָא פִּתְגָמָא דַיְיָ עִמֵהּ לְמֵימַר לָא יִרְתִינָךְ דֵין אֱלָהֵין בַּר דְתוֹלִיד הוּא יִרְתִינָךְ:
@67 וְאַפֵּיק יָתֵהּ לְבָרָא וַאֲמַר אִסְתְּכִי כְעַן לִשְׁמַיָא וּמְנֵי כּוֹכְבַיָא אִם תִּכּוֹל לְמִמְנֵי יָתְהוֹן וַאֲמַר לֵיהּ כְּדֵין יְהוֹן בְּנָךְ:
@68 וְהֵימִין בְּמֵימְרָא דַיְיָ וְחָשְׁבַהּ לֵיהּ לְזָכוּ:
@69 וַאֲמַר לֵהּ אֲנָא יְיָ דְאַפֵּקְתָּךְ מֵאוּרָא דְכַשְׂדָאֵי לְמִתַּן לָךְ יָת אַרְעָא הָדָא לְמֵירְתַהּ:
@70 וַאֲמָר יְיָ אֱלֹהִים בְּמָה אִידַע אֲרֵי אֵרְתִנַהּ:
@71 וַאֲמַר לֵהּ קָרֵב קֳדָמַי עֶגְלִין תְּלָתָא וְעִזִין תְּלָתָא וְדִכְרִין תְּלָת וְשַׁפְנִינָא וּבַר יוֹנָה:
@72 וְקָרֵב קֳדָמוֹהִי יָת כָּל אִלֵין וּפַלִיג יָתְהוֹן בְּשָׁוֶה וִיהַב פַּלְגַיָא פִּלוּג לָקֳבֵיל חַבְרֵיהּ וְיָת עוֹפָא לָא פַּלִיג:
@73 וּנְחַת עוֹפָא עַל פַּגְלַיָא וְאַפְרַח יָתְהוֹן אַבְרָם:
@74 וַהֲוָה שִׁמְשָׁא לְמֵיעַל וְשִׁינְתָא נְפָלַת עַל אַבְרָם וְהָא אֵימָתָא קְבֵל סַגִי נְפָלַת עֲלוֹהִי:
@75 וַאֲמַר לְאַבְרָם מִדַע תִּדַע אֲרֵי דַיָרִין יְהוֹן בְּנָיךְ בְּאַרְעָא דְלָא דִילְהוֹן וְיִפְלְחוּן בְּהוֹן וִיעַנוּן יָתְהוֹן אַרְבַּע מְאָה שְׁנִין:
@76 וְאַף יָת עַמָא דְיִפְלְחוּן בְּהוֹן דָיִין אֲנָא וּבָתַר כֵּן יִפְקוּן בְּקִנְיָנָא סַגִי:
@77 וְאַתְּ תֵעוֹל לְוָת אַבָהָתָךְ בִּשְׁלָם תִּתְקְבַר בְּסֵיבוּ טָבָא:
@78 וְדָרָא רְבִיעָאָה יְתוּבוּן הָכָא אֲרֵי לָא שְׁלִים חוֹבָא דֶאֱמוֹרָאָה עַד כְּעָן:
@79 וַהֲוָה שִׁמְשָׁא עַלַת וְקִבְלָא הֲוָה וְהָא תַּנוּר דִתְנַן וּבָעוּר דְאֶשָׁתָא דִעֲדָא בֵּין פַּלְגַיָא הָאִלֵין:
@80 בְּיוֹמָא הַהוּא גְזַר יְיָ עִם אַבְרָם קְיָם לְמֵימָר לִבְנָךְ יְהָבִית יָת אַרְעָא הָדָא מִן נַהֲרָא דְמִצְרַיִם וְעַד נַהֲרָא רַבָּא נַהֲרָא פְרָת:
@81 יָת שַׁלְמָאֵי וְיָת קְנִזָאֵי וְיָת קַדְמוֹנָאֵי:
@82 וְיָת חִתָּאֵי וְיָת פְּרִזָאֵי וְיָת גִבָּרָאֵי:
@83 וְיָת אֱמוֹרָאֵי וְיָת כְנַעֲנָאֵי וְיָת גִרְגָשָׁאֵי וְיָת יְבוּסָאֵי:
@84 וְשָׂרַי אִתַּת אַבְרָם לָא יְלִידַת לֵהּ וְלַהּ אַמְתָא מִצְרֵיתָא וּשְׁמַהּ הָגָר:
@85 וַאֲמַרַת שָׂרַי לְאַבְרָם הָא כְעַן מַנְעֲנִי יְיָ מִלְמֵילַד עוּל כְּעַן לְוַת אַמְתִי מָאִים אִתְבְּנֵי מִנַהּ וְקַבִּיל אַבְרָם לְמֵימַר שָׂרָי:
@86 וּדְבָרַת שָׂרַי אִתַּת אַבְרָם יָת הָגָר מִצְרֵיתָא אַמְתַהּ מִסוֹף עֲשַׂר שְׁנִין לְמִיתַּב אַבְרָם בְּאַרְעָא דִכְנָעַן וִיהָבַת יָתַהּ לְאַבְרָם בַּעֲלַהּ לֵהּ לְאִנְתּוּ:
@87 וְעַל לְוַת הָגָר וְעַדִיאַת וַחֲזַת אֲרֵי עֲדִיאַת וּקְלַת רִבָּנְתַּהּ בְּעֵינָהַהּ:
@88 וַאֲמַרַת שָׂרַי לְאַבְרָם דִין לִי עֲלָךְ אֲנָא יְהָבִית אַמְתִי לָךְ וַחֲזַת אֲרֵי עֲדִיאַת וּקְלֵית בְּעֵינָהַהּ יְדִין יְיָ בֵּינִי וּבֵינָךְ:
@89 וַאֲמַר אַבְרָם לְשָׂרַי הָא אַמְתִיךְ בִּידִךְ עִבִידִי לַהּ כִּדְתַקִין בְעֵינָיְכִי וְעֲנִיתַהּ שָׂרַי וְעָרְקַת מִקֳדָמָהַהּ:
@90 וְאַשְׁכְּחַהּ מַלְאָכָא דַיְיָ עַל עֵינָא דְמַיָא בְּמַדְבְּרָא עַל עֵינָא בְּאָרְחָא דְחַגְרָא:
@91 וַאֲמַר הָגָר אַמְתָא דְשָׂרַי מְנָן אַתְּ אָתְיָא וּלְאָן אַתְּ אָזְלָא וַאֲמַרַת מִן קֳדָם שָׂרַי רִבָּנְתִּי אֲנָא עֲרָקָא (עֲרָקַת):
@92 וַאֲמַר לַהּ מַלְאֲכָא דַיְיָ תּוּבִי לְוַת רִבּוֹנְתִּיךְ וְאִשְׁתַּעְבְּדִי תְּחוֹת יְדָהָא:
@93 וַאֲמַר לַהּ מַלְאֲכָא דַיְיָ אַסְגָאָה אַסְגֵי יָת בְּנָיְכִי וְלָא יִתִּמְנוּן מִסְגֵי:
@94 וַאֲמַר לַהּ מַלְאֲכָא דַיְיָ הָא אַתְּ מְעַדְיָא וְתֵלְדִין בַּר וְתִקְרִין שְׁמֵהּ יִשְׁמָעֵאל אֲרֵי קַבִּיל יְיָ צְלוֹתִיךְ:
@95 וְהוּא יְהֵא מָרוֹד בֶּאֱנָשָׁא הוּא יְהֵא צְרִיךְ לְכֹלָא וְאַף כָּל בְנֵי אֲנָשָׁא יְהוֹן צְרִיכִין לֵהּ וְעַל אַפֵּי כָל אֲחוֹהִי יִשְׁרֵי:
@96 וְצַלִיאַת בִּשְׁמָא דַיְיָ דְמִתְמַלֵל עִמַהּ אֲמַרַת אַתְּ הוּא אֱלָהָא דְחָזֵי כֹלָא אֲרֵי אֲמַרַת הַבְרַם הָכָא (נ''א הַאַף אֲנָא) שָּׁרֵיתִי חַזְיָא בָּתַר דְאִתְגְלִי לִי:
@97 עַל כֵּן קְרָא לִבְאֵרָא בְּאֵרָא דְמַלְאַךְ קַיָימָא אִתַּחֲזִי עֲלַהּ הָא הִיא בֵּין רְקָם וּבֵין חַגְרָא:
@98 וִילִידַת הָגָר לְאַבְרָם בָּר וקְרָא אַבְרָם שׁוּם בְּרֵיהּ דִילִידַת הָגָר יִשְׁמָעֵאל:
@99 וְאַבְרָם בַּר תְּמָנָן וְשִׁית שְׁנִין כַּד יְלִידַת הָגָר יָת יִשְׁמָעֵאל לְאַבְרָם:
@100 וַהֲוָה אַבְרָם בַּר תִּשְׁעִין וּתְשַׁע שְׁנִין וְאִתְגְלִי יְיָ לְאַבְרָם וַאֲמַר לֵיהּ אֲנָא אֵל שַׁדַי פְּלַח קֳדָמַי וֶהֱוֵי שְׁלִים:
@101 וְאֶתֵּן קְיָמִי בֵּין מֵימְרִי וּבֵינָךְ וְאַסְגֵי יָתָךְ לַחֲדָא לַחֲדָא:
@102 וּנְפַל אַבְרָם עַל אַפּוֹהִי וּמַלֵיל עִמֵהּ יְיָ לְמֵימָר:
@103 אֲנָא הָא (גְזַר) קְיָמִי עִמָךְ וּתְהֵי לְאַב סַגִי עַמְמִין:
@104 וְלָא יִתְקְרֵי עוֹד יָת שְׁמָּךְ אַבְרָם וִיהֵי שְׁמָךְ אַבְרָהָם אֲרֵי אַב סַגִי עַמְמִין יְהָבִתָךְ:
@105 וְאַפִּישׁ יָתָךְ לַחֲדָא לַחֲדָא וְאֶתְּנִנָךְ לְכִנְשִׁין וּמַלְכִין דְשַׁלִיטִין בְּעַמְמַיָא מִנָךְ יִפְקוּן:
@106 וַאַקֵים יָת קְיָמִי בֵּין מֵימְרִי וּבֵינָךְ וּבֵין בְּנָךְ בַּתְרָךְ לְדָרֵיהוֹן לִקְיָם עָלָם לְמֵהֲוֵי לָךְ לֵאלָהָא וְלִבְנָיךְ בַּתְרָךְ:
@107 וְאֶתֵּן לָךְ וְלִבְנָיךְ בַּתְרָךְ יָת אַרְעָא תּוֹתָבוּתָךְ יָת כָּל אַרְעָא דִכְנַעַן לְאַחֲסָנַת עָלָם וְאֱהֶוֵי לְהוֹן לֵאלָהָא:
@108 וַאֲמַר יְיָ לְאַבְרָהָם וְאַתְּ יָת קְיָמִי תִטָר אַתְּ וּבְנָךְ בַּתְרָךְ לְדָרֵיהוֹן:
@109 דָא קְיָמִי דִי תִטְרוּן בֵּין מֵימְרִי וּבֵינֵיכוֹן וּבֵין בְּנָיךְ בַּתְרָךְ מִגְזַר לְכוֹן כָּל דְכוּרָא:
@110 וְתִגְזְרוּן יָת בִּשְׂרָא דְעָרְלָתְכוֹן וּתְהֵי (נ''י וּתְהֵא) לְאָת קְיָם בֵּין מֵימְרִי וּבֵינֵיכוֹן:
@111 וּבַר תְּמַנְיָא יוֹמִין יִתְגְזַר (יִגְזַר) לְכוֹן כָּל דְכוּרָא לְדָרָתֵיכוֹן יְלִידֵי בֵּיתָא וּזְבִינֵי כַּסְפָּא מִכֹּל בַּר עַמְמִין דְלָא מִבְּנָךְ הוּא:
@112 אִתְגַזָרָא יִתְגַזְרוּן (נ''י מִגְזַר יִגְזַר) יְלִיד בֵּיתָךְ וּזְבִין כַּסְפָּךְ וּתְהֵי קְיָמִי בְּבִשְׂרֵיכוֹן לִקְיָם עָלָם:
@113 וְעָרֵל דְכוּרָא דִי לָא יִגְזַר יָת בְּשַׂר עָרְלָתֵהּ וְיִשְׁתֵּיצֵי אֱנָשָׁא הַהוּא מֵעַמֵּיהּ יָת קְיָמִי אַשְׁנִי:
@114 וַאֲמַר יְיָ לְאַבְרָהָם שָׂרַי אִתְּתָךְ לָא תִקְרֵי יָת שְׁמַהּ שָׂרָי אֲרֵי שָׂרָה שְׁמַהּ:
@115 וֶאֱבָרֵךְ יָתַהּ וְאַף אֶתֵּן מִנַהּ לָךְ בָּר וֶאֱבָרֲכִנַהּ וּתְהֵי לְכִנְשִׁין מַלְכִין דְשַׁלִּיטִין בְעַמְמַיָּא מִנַהּ יְהוֹן:
@116 וּנְפַל אַבְרָהָם עַל אַפּוֹהִי וַחֲדִי וַאֲמַר בְּלִבֵּהּ הַלְּבַר מְאָה שְׁנִין יְהֵי וְלַד וְאִם שָׂרָה הֲבַת תִּשְׁעִין שְׁנִין תְּלִיד:
@117 וַאֲמַר אַבְרָהָם קֳדָם יְיָ לְוַי יִשְׁמָעֵאל יִתְקַיָּם קֳדָמָךְ:
@118 וַאֲמַר יְיָ בְּקוּשְׁטָא שָׂרָה אִתְּתָךְ תְּלִיד לָךְ בָּר וְתִקְרֵי יָת שְׁמֵהּ יִצְחָק וַאֲקִים יָת קְיָמִי עִמֵּהּ לִקְיָם עָלָם לִבְנוֹהִי בַּתְרוֹהִי:
@119 וְעַל יִשְׁמָעֵאל קַבֵּלִית צְלוֹתָךְ הָא בָּרֵכִית יָתֵהּ וְאַפֵּישּׁ יָתֵהּ וְאַסְגֵּי יָתֵהּ לַחֲדָא לַחֲדָא תְּרֵין עֲשַׂר רַבְרְבַיָּא יְלִיד וְאֶתְּנִנֵּיהּ לְעַם סַגִּי:
@120 וְיָת קְיָמִי אָקִים עִם יִצְחָק דִי תְלִיד לָךְ שָׂרָה לְזִמְנָא הָדֵין בְּשַׁתָּא אָחֳרַנְתָּא:
@121 וְשֵׁיצֵי לְמַלָּלָא עִמֵהּ וְאִסְתַּלַּק יְקָרָא דַיְיָ מֵעִלָּווֹהִי דְּאַבְרָהָם:
@122 וּדְבַר אַבְרָהָם יָת יִשְׁמָעֵאל בְּרֵהּ וְיָת כָּל יְלִידֵי בֵיתֵהּ וְיָת כָּל זְבִינֵי כַסְפֵּה כָּל דְּכוּרָא בַּאֲנָשֵׁי בֵּית אַבְרָהָם וּגְזַר יָת בִּשְׂרָא דְעָרְלָתְהוֹן בִּכְרַן יוֹמָא הָדֵין כְּמָא דִי מַלֵיל עִמֵּהּ יְיָ:
@123 וְאַבְרָהָם בַּר תִּשְׁעִין וּתְשַׁע שְׁנִין כַּד גְזַר בִּשְׂרָא דְעָרְלְתֵהּ:
@124 וְיִשְׁמָעֵאל בְּרֵהּ בַּר תְּלַת עַשְׂרֵי שְׁנִין כַּד גְּזַר יַת בִּשְׂרָא דְעָרְלְתֵהּ:
@125 בִּכְרַן יוֹמָא הָדֵין (גְּזַר) אִתְגְּזַר אַבְרָהָם וְיִשְׁמָעֵאל בְּרֵהּ:
@126 וְכָל אֱנָשֵׁי בֵיתֵהּ יְלִידֵי בֵיתָא וּזְבִינֵי כַסְפָּא מִן בַּר עַמְמִין אִתְגְּזָרוּ (גְזָרוּ) עִמֵּהּ: פפפ:

@1 **לך לך.** להנאתך ולטובתך, ושם אעשך לגוי גדול, וכאן אי אתה זוכה לבנים. ועוד שאודיע טבעך בעולם:
@2 **ואעשך לגוי גדול.** לפי שהדרך גורמת לשלשה דברים ממעטת פריה ורביה, וממעטת את הממון, וממעטת את השם, לכך הזקק לשלש ברכות הללו שהבטיחו על הבנים, ועל הממון, ועל השם. (וזהו ואגדלה שמך, הריני מוסיף אות על שמך, שעד עכשיו שמך אברם מכאן ואלך אברהם, ואברהם עולה רמ''ח כנגד איבריו של אדם) : **ואברכך.** בממון: **והיה ברכה.** הברכות נתנות בידך, עד עכשיו היו בידי, ברכתי את אדם ואת נח ואותך, ומעכשיו אתה תברך את אשר תחפוץ. דבר אחר ואעשך לגוי גדול זהו שאומרים אלהי אברהם, ואברכך זהו שאומרים אלהי יצחק, ואגדלה שמך זהו שאומרים אלהי יעקב. יכול יהיו חותמין בכלן, תלמוד לומר והיה ברכה, בך חותמין ולא בהם: **מארצך.** והלא כבר יצא משם עם אביו ובא עד לחרן, אלא כך אמר לו התרחק עוד משם וצא מבית אביך: **אל הארץ אשר אראך.** לא גלה לו הארץ מיד, כדי לחבבה בעיניו, ולתת לו שכר על כל דבור ודבור. כיוצא בו (בראשית כב ב) את בנך את יחידך אשר אהבת את יצחק, כיוצא בו (כב ב) על אחד ההרים אשר אמר אליך, כיוצא בו (יונה ג ב) וקרא עליה את הקריאה אשר אנכי דובר אליך:
@3 **ונברכו בך כל משפחת האדמה.** יש אגדות רבות, וזהו פשוטו אדם אומר לבנו תהא כאברהם, וכן כל ונברכו בך שבמקרא, וזה מוכיח (בראשית מח כ) בך יברך ישראל לאמר ישימך אלהים כאפרים וכמנשה:
@5 **אשר עשו בחרן.** שהכניסן תחת כנפי השכינה, אברהם מגיר את האנשים, ושרה מגירת הנשים, ומעלה עליהם הכתוב כאלו עשאום. ופשוטו של מקרא עבדים ושפחות שקנו להם, כמו (שם לא א) עשה את כל הכבוד הזה, (במד' כד יח) וישראל עשה חיל, לשון קונה וכונס:
@6 **ויעבר אברם בארץ.** נכנס לתוכה: **עד מקום שכם.** להתפלל על בני יעקב כשיבאו להלחם בשכם: **אלון מורה.** הוא שכם, הראהו הר גריזים והר עיבל ששם קבלו ישראל שבועת התורה: **והכנעני אז בארץ.** היה הולך וכובש את ארץ ישראל מזרעו של שם, שבחלקו של שם נפלה כשחלק נח את הארץ לבניו, שנאמר (בראשית יד יח) ומלכי צדק מלך שלם, לפיכך (פסוק ז) ויאמר ה' אל אברם לזרעך אתן את הארץ הזאת, עתיד אני להחזירה לבניך שהם מזרעו של שם:
@7 **ויבן שם מזבח.** על בשורת הזרע ועל בשורת ארץ ישראל:
@8 **ויעתק משם.** אהלו: **מקדם לבית אל.** במזרחה של בית אל. נמצאת בית אל במערבו, והוא שנאמר בית אל מים: **אהלו.** אהלה כתיב, בתחלה נטה את אהל אשתו ואחר כך את שלו: **ויבן שם מזבח.** נתנבא שעתידין בניו להכשל שם על עון עכן והתפלל שם עליהם:
@9 **הלוך ונסוע.** לפרקים, יושב כאן חדש או יותר ונוסע משם ונוטה אהלו במקום אחר, וכל מסעיו הנגבה ללכת לדרומה של ארץ ישראל והוא לצד ירושלים שהיא בחלקו של יהודה, שנטלו בדרומה של ארץ ישראל הר המוריה שהיא נחלתו:
@10 **רעב בארץ.** באותה ארץ לבדה, לנסותו אם יהרהר אחר דבריו של הקדוש ברוך הוא שאמר לו ללכת אל ארץ כנען, ועכשיו משיאו לצאת ממנה:
@11 **הנה נא ידעתי.** מדרש אגדה עד עכשיו לא הכיר בה מתוך צניעות שבשניהם, ועכשיו על ידי מעשה הכיר בה. דבר אחר מנהג העולם שעל ידי טורח הדרך אדם מתבזה, וזאת עמדה ביפיה. ופשוטו של מקרא הנה נא הגיע השעה שיש לדאוג על יפיך, ידעתי זה ימים רבים כי יפת מראה את, ועכשיו אנו באים בין אנשים שחורים ומכוערים, אחיהם של כושים, ולא הרגלו באשה יפה. ודומה לו (בראשית יט ב) הנה נא אדני סורו נא:
@13 **למען ייטב לי בעבורך.** יתנו לי מתנות:
@14 **ויהי כבוא אברם מצרימה.** היה לו לומר כבואם מצרימה, אלא למד שהטמין אותה בתבה ועל ידי שתבעו את המכס פתחו וראו אותה:
@15 **ויהללו אותה אל פרעה.** הללוה ביניהם לומר הגונה זו למלך:
@16 **ולאברם היטיב.** פרעה **בעבורה.** [נתן לו מתנות]:
@17 **וינגע ה'** וגו' **.** במכת ראתן לקה, שהתשמיש קשה לו: **ואת ביתו.** כתרגומו ועל אנש ביתיה (ומדרשו לרבות כותליו ועמודיו וכליו) : **על דבר שרי.** על פי דבורה, אומרת למלאך הך והוא מכה:
@19 **קח ולך.** לא כאבימלך שאמר לו (כ טו) הנה ארצי לפניך, אלא אמר לו לך ואל תעמד, שהמצרים שטופי זמה הם, שנאמר (יחזקאל כג כ) וזרמת סוסים זרמתם:
@20 **ויצו עליו.** על אודותיו לשלחו ולשמרו: **וישלחו.** כתרגומו ואלויאו:
@21 **ויעל אברם** וגו' **הנגבה.** לבא לדרומה של ארץ ישראל כמו שאמור למעלה (פסוק ט) הלוך ונסוע הנגבה, להר המוריה, ומכל מקום כשהוא הולך ממצרים לארץ כנען מדרום לצפון הוא מהלך, שארץ מצרים בדרומה של ארץ ישראל, כמו שמוכיח במסעות ובגבולי הארץ:
@22 **כבד מאד.** טעון משאות:
@23 **וילך למסעיו.** כשחזר ממצרים לארץ כנען היה הולך ולן באכסניות שלן בהם בהליכתו למצרים. למדך דרך ארץ שלא ישנה אדם מאכסניא שלו. דבר אחר בחזרתו פרע הקפותיו: **מנגב.** ארץ מצרים בדרומה של ארץ כנען:
@24 **אשר עשה שם בראשנה ויקרא שם.** ואשר קרא שם אברם בשם ה'. וגם יש לומר ויקרא שם עכשיו בשם ה':
@25 **ההולך את אברם.** מי גרם שהיתה לו זאת, הליכתו עם אברם:
@26 **ולא נשא אתם.** לא היתה יכולה להספיק מרעה למקניהם, ולשון קצר הוא, וצריך להוסיף עליו, כמו ולא נשא אותם מרעה הארץ, לפיכך כתוב ולא נשא בלשון זכר:
@27 **ויהי ריב.** לפי שהיו רועים של לוט רשעים ומרעים בהמתם בשדות אחרים, ורועי אברם מוכיחים אותם על הגזל, והם אומרים נתנה הארץ לאברם, ולו אין יורש, ולוט יורשו, ואין זה גזל, והכתוב אומר והכנעני והפרזי אז ישב בארץ ולא זכה בה אברם עדיין:
@28 **אנשים אחים.** קרובים. ומדרש אגדה דומין בקלסתר פנים:
@29 **אם השמאל ואימנה.** בכל אשר תשב, לא אתרחק ממך ואעמוד לך למגן ולעזר. וסוף דבר הצרך לו שנאמר (יד יד) וישמע אברם כי נשבה אחיו וגו' : **ואימנה.** אימין את עצמי, כמו ואשמאילה אשמאיל את עצמי. ואם תאמר היה לו לנקד ואימינה, כך מצינו במקום אחר (ש''ב יד יט) אם אש להמין ואין נקוד להימין:
@30 **כי כלה משקה.** ארץ נחלי מים: **לפני שחת ה' את סדום ואת עמורה.** היה אותו מישור: **כגן ה'.** לאילנות: **כארץ מצרים.** לזרעים: **באכה צער.** עד צער. ומדרש אגדה דורשה לגנאי, על שהיו שטופי זמה בחר לו לוט בשכונתם במסכת הוריות (י ב) :
@31 **ככר.** מישור, כתרגומו: **מקדם.** נסע מאצל אברם והלך לו למערבו של אברם, נמצא נוסע ממזרח למערב. ומדרש אגדה הסיע עצמו מקדמונו של עולם אמר אי אפשי לא באברם ולא באלהיו:
@32 **ויאהל.** נטה אהלים לרועיו ולמקנהו עד סדום:
@33 **ואנשי סדום רעים.** ואף על פי כן לא נמנע לוט מלשכון עמהם. ורבותינו למדו מכאן (משלי י ז) שם רשעים ירקב: **רעים.** בגופם: **וחטאים.** בממונם: **לה' מאד.** יודעים רבונם ומתכונים למרוד בו:
@34 **אחרי הפרד לוט.** כל זמן שהרשע עמו היה הדבור פורש ממנו:
@36 **אשר אם יוכל איש.** כשם שאי אפשר לעפר להמנות, כך זרעך לא ימנה:
@38 **ממרא.** שם אדם:
@39 **אמרפל.** הוא נמרוד שאמר לאברהם פול לתוך כבשן האש: **מלך גוים.** מקום יש ששמו גוים, על שם שנתקבצו שמה מכמה אמות ומקומות והמליכו איש עליהם ושמו תדעל:
@40 **ברע.** רע לשמים ורע לבריות: **ברשע.** שנתעלה ברשעו: **שנאב.** שונא אביו שבשמים: **שמאבר.** שם אבר לעוף ולקפוץ ולמרוד בהקדוש ברוך הוא: **בלע.** שם העיר:
@41 **עמק השדים.** כך שמו, על שם שהיו בו שדות הרבה: **הוא ים המלח.** לאחר זמן נמשך הים לתוכו ונעשה ים המלח. ומדרש אגדה אומר שנתבקעו הצורים סביבותיו ונמשכו יאורים לתוכו:
@42 **שתים עשרה שנה עבדו.** חמשה מלכים הללו את כדרלעומר:
@43 **ובארבע עשרה שנה.** למרדן, **בא כדרלעומר' לפי שהוא היה בעל המעשה נכנס בעבי הקורה: והמלכים.** אלה שלשה מלכים: **הזוזים.** הם זמזמים:
@44 **בהררם.** בהר שלהם: **איל פארן.** כתרגומו מישור. ואומר אני שאין איל לשון מישור, אלא מישור של פארן איל שמו, ושל ממרא אלוני שמו, ושל ירדן ככר שמו, ושל שטים אבל שמו אבל השטים, וכן בעל גד בעל שמו, וכלם מתורגמין מישור, וכל אחד שמו עליו: **על המדבר.** אצל המדבר, כמו (במדבר ב כ) ועליו מטה מנשה:
@45 **עין משפט הוא קדש.** על שם העתיד, שעתידין משה ואהרן להשפט שם על עסקי אותו העין, והם מי מריבה. ואונקלוס תרגמו כפשוטו, מקום שהיו בני המדינה מתקבצים שם לכל משפט: **שדה העמלקי.** עדיין לא נלד עמלק ונקרא על שם העתיד: **בחצצון תמר.** הוא עין גדי, מקרא מלא (דה''י ב' כ ב) ביהושפט:
@47 **ארבעה מלכים את החמשה.** ואף על פי כן נצחו המועטים, להודיעך שגבורים היו, ואף על פי כן לא נמנע אברהם מלרדוף אחריהם:
@48 **בארת בארת חמר.** בארות הרבה היו שם שנוטלין משם אדמה לטיט של בנין. ומדרש אגדה שהיה הטיט מגבל בהם, ונעשה נס למלך סדום שיצא משם, לפי שהיו באמות מקצתן שלא היו מאמינין שנצל אברהם מאור כשדים מכבשן האש, וכיון שיצא זה מן החמר האמינו באברהם למפרע: **הרה נסו.** להר נסו. הרה כמו להר, כל תבה שצריכה למ''ד בתחלתה הטיל לה ה''א בסופה. ויש חלוק בין הרה לההרה שה''א שבסוף התבה עומדת במקום למ''ד שבראשה, אבל אינה עומדת במקום למ''ד ונקודה פת''ח תחתיה, והרי הרה כמו להר, או כמו אל הר, ואינו מפרש לאיזה הר, אלא שכל אחד נס כאשר מצא הר תחלה, וכשהוא נותן ה''א בראשה לכתוב ההרה או המדברה, פתרונו כמו אל ההר או כמו לההר, ומשמע לאותו הר הידוע ומפורש בפרשה:
@50 **והוא ישב בסדום.** מי גרם לו זאת, ישיבתו בסדום:
@51 **ויבא הפליט.** [מדרשו] לפי פשוטו זה עוג שפלט מן המלחמה, והוא שכתוב (דברים ג יא) כי רק עוג נשאר מיתר הרפאים, וזהו נשאר שלא הרגוהו אמרפל וחבריו כשהכו את הרפאים בעשתרות קרנים, תנחומא (חוקת כה) . ומדרש בראשית רבה (מב ח) זה עוג שפלט מדור המבול, וזהו מיתר הרפאים שנאמר (ו ד) הנפלים היו בארץ וגו' ומתכון שיהרג אברהם וישא את שרה: **העברי.** שבא מעבר הנהר: **בעלי ברית אברם.** שכרתו עמו ברית (דבר אחר שהשיאו לו עצה על המילה כמו שמפורש במקום אחר) :
@52 **וירק.** כתרגומו וזרז, וכן (ויקרא כו לג) והריקתי אחריכם חרב, אזדיין בחרבי עליכם, וכן (שמות טו ט) אריק חרבי, וכן (תהלים לה ג) והרק חנית וסגר: **חניכיו.** חנכו כתיב זה אליעזר שחנכו למצוות והוא לשון התחלת כניסת האדם או כלי לאמנות שהוא עתיד לעמוד בה, וכן (משלי כב ו) חנך לנער, (במדבר ז יא) חנכת המזבח, (תהלים ל א) חנכת הבית ובלע''ז קורין לו איניציי''ר : **שמנה עשר ושלש מאות.** רבותינו אמרו אליעזר לבדו היה, והוא מנין גימטריא של שמו: **עד דן.** שם תשש כחו, שראה שעתידין בניו להעמיד שם עגל:
@53 **ויחלק עליהם.** לפי פשוטו, סרס המקרא, ויחלק הוא ועבדיו עליהם לילה כדרך הרודפים שמתפלגים אחר הנרדפים כשבורחים זה לכאן וזה לכאן: **לילה.** כלומר אחר שחשכה לא נמנעו מלרדפם. ומדרש אגדה שנחלק הלילה ובחציו הראשון נעשה לו נס, וחציו השני נשמר ובא לו לחצות לילה של מצרים: **עד חובה.** אין מקום ששמו חובה, אלא דן קורא חובה על שם עבודה זרה שעתידה להיות שם:
@55 **עמק שוה.** כך שמו כתרגומו למישר מפנא, פנוי מאילנות ומכל מכשול: **עמק המלך.** בית ריסא דמלכא, בית ריס אחד שהוא שלשים קנים, שהיה מיוחד למלך לשחק שם. ומדרש אגדה עמק שהשוו שם כל האמות והמליכו את אברהם עליהם לנשיא אלהים ולקצין:
@56 **ומלכי צדק.** מדרש אגדה הוא שם בן נח: **לחם ויין.** כך עושים ליגיעי מלחמה, והראה לו שאין בלבו עליו על שהרג את בניו. ומדרש אגדה רמז לו על המנחות ועל הנסכים שיקריבו שם בניו:
@57 **קנה שמים וארץ.** כמו (תהלים קלד ג) עשה שמים וארץ, על ידי עשיתן קנאן להיות שלו:
@58 **אשר מגן.** אשר הסגיר, וכן (הושע יא ח) אמגנך ישראל: **ויתן לו.** אברם, מעשר מכל אשר לו לפי שהיה כהן:
@59 **תן לי הנפש.** מן השבי שלי שהצלת, החזר לי הגופים לבדם:
@60 **הרימתי ידי.** לשון שבועה, מרים אני את ידי לאל עליון וכן (בראשית כב טז) בי נשבעתי, נשבע אני, וכן (שם כג יג) נתתי כסף השדה קח ממני, נותן אני לך כסף השדה וקחהו ממני:
@61 **אם מחוט ועד שרוך נעל.** אעכב לעצמי מן השבי: **ואם אקח מכל אשר לך.** ואם תאמר לתת לי שכר מבית גנזיך, לא אקח: **ולא תאמר אני העשרתי את אברם.** שהקדוש ברוך הוא הבטיחני לעשרני, שנאמר לעיל (יב ב) ואברכך וגו' :
@62 **הנערים.** עבדי אשר הלכו אתי, ועוד ענר אשכל וממרא וגו' . ואף על פי שעבדי נכנסו למלחמה, שנאמר לעיל (פסוק טו) הוא ועבדיו ויכם, וענר וחבריו ישבו על הכלים לשמר, אפלו הכי הם יקחו חלקם. וממנו למד דוד שאמר (ש''א ל כד) כחלק הירד למלחמה וכחלק הישב על הכלים יחדו יחלקו. לכך נאמר (שם פסוק כה) ויהי מהיום ההוא ומעלה וישמה לחק ולמשפט, ולא נאמר והלאה לפי שכבר נתן החוק בימי אברהם:
@63 **אחר הדברים האלה.** כל מקום שנאמר אחר סמוך, אחרי מפלג. אחר שנעשה לו נס זה שהרג את המלכים והיה דואג ואומר שמא קבלתי שכר על כל צדקתי, לכך אמר לו המקום אל תירא אברם אנכי מגן לך מן הענש שלא תענש על כל אותן נפשות שהרגת, ומה שאתה דואג על קבול שכרך, שכרך הרבה מאד:
@64 **הולך ערירי.** מנחם בן סרוק פרשו לשון יורש, וחבר לו (מלאכי ב יב) ער וענה, ערירי בלא יורש, כאשר תאמר (איוב לא יב) ובכל תבואתי תשרש, תעקר שרשיה, כך לשון ערירי חסר בנים, ובלע''ז דישאנפנטי''ף . ולי נראה ער וענה מגזרת (שיר השירים ה ב) ולבי ער, וערירי לשון חרבן, וכן (תהל' קלז ז) ערו ערו, וכן (חבק' ג יג) ערות יסוד, וכן (ירמיה נא נח) ערער תתערער, וכן (צפניה ב יד) כי ארזה ערה: **ובן משק ביתי.** כתרגומו, שכל ביתי נזון על פיו, כמו (בראשית מא מ) ועל פיך ישק, אפטורפס שלי, ואלו היה לי בן היה בני ממנה על שלי: **דמשק.** לפי התרגום מדמשק היה, ולפי מדרש אגדה שרדף המלכים עד דמשק. ובתלמוד דרשו נוטריקון דולה ומשקה מתורת רבו לאחרים:
@65 **הן לי לא נתת זרע.** ומה תועלת בכל אשר תתן לי:
@67 **ויוצא אתו החוצה.** לפי פשוטו הוציאו מאהלו לחוץ לראות הכוכבים, ולפי מדרשו אמר לו צא מאצטגנינות שלך שראית במזלות שאינך עתיד להעמיד בן, אברם אין לו בן, אבל אברהם יש לו בן. וכן שרי לא תלד, אבל שרה תלד, אני קורא לכם שם אחר וישתנה המזל. דבר אחר הוציאו מחללו של עולם והגביהו למעלה מן הכוכבים, וזהו לשון הבטה מלמעלה למטה:
@68 **והאמין בה'.** לא שאל לו אות על זאת, אבל על ירשת הארץ שאל לו אות ואמר לו במה אדע: **ויחשבה לו צדקה.** הקדוש ברוך הוא חשבה לאברם לזכות ולצדקה על האמונה שהאמין בו. דבר אחר במה אדע, לא שאל לו אות אלא אמר לפניו הודיעני באיזה זכות יתקימו בה, אמר לו הקדוש ברוך הוא בזכות הקרבנות:
@71 **עגלה משלשת.** שלשה עגלים, רמז לשלשה פרים פר יום הכפורים, ופר העלם דבר של צבור, ועגלה ערופה: **ועז משלשת.** רמז לשעיר הנעשה בפנים, ושעירי מוספין של מועד, ושעיר חטאת יחיד: **ואיל משלש.** אשם ודאי, ואשם תלוי, וכבשה של חטאת יחיד: **ותור וגוזל.** תור ובן יונה:
@72 **ויבתר אתם.** חלק כל אחד לשני חלקים, ואין המקרא יוצא מידי פשוטו לפי שהיה כורת עמו ברית לשמור הבטחתו להוריש לבניו את הארץ, כדכתיב (פסוק יח) ביום ההוא כרת ה' את אברם ברית לאמר וגו' , ודרך כורתי ברית לחלק בהמה ולעבר בין בתריה, כמה שנאמר להלן (ירמיה לד יט) העוברים בין בתרי העגל, אף כאן תנור עשן ולפיד אש אשר עבר בין הגזרים הוא שלוחו של שכינה שהוא אש: **ואת הצפור לא בתר.** לפי שהאמות נמשלו לפרים ואילים ושעירים, שנאמר (תהלים כב יג) סבבוני פרים רבים וגו' , ואומר (דניאל ח כ) והאיל אשר ראית בעל הקרנים מלכי מדי ופרס. ואומר (שם כא) והצפיר השעיר מלך יון, וישראל נמשלו לבני יונה שנאמר (שה''ש ב יד) יונתי בחגוי הסלע, לפיכך בתר הבהמות רמז על האמות שיהיו כלין והולכין, ואת הצפור לא בתר רמז שיהיו ישראל קימין לעולם:
@73 **העיט.** הוא עוף, ועל שם שהוא עט ושואף הנבלות (איוב ט כו) לטוש עלי אכל, כמו (שמואל א' טו יט) ותעט אל השלל: **על הפגרים.** על הבתרים (הפגרים מתרגמינן פגליא, אלא מתוך שהרגלו לתרגם (פסוק י) איש בתרו, ויהב פלגיא, נתחלף להם תבת פגליא לפלגיא, ותרגמו הפגרים פלגיא, וכל המתרגם כן טועה, לפי שאין להקיש בתרים לפגרים, שבתרים תרגומו פלגיא, ופגרים תרגומו פגליא לשון פגול, כמו (ויקרא יט ז) פגול הוא לשון פגר) : **וישב.** לשון נשיבה והפרחה, כמו (תהל' קמז יח) ישב רוחו, רמז שיבא דוד בן ישי לכלותם, ואין מניחין אותו מן השמים עד שיבא מלך המשיח:
@74 **והנה אימה** וגו' **.** רמז לצרות וחשך של גליות:
@75 **כי גר יהיה זרעך.** משנלד יצחק עד שיצאו ישראל ממצרים ארבע מאות שנה. כיצד, יצחק בן ששים שנה כשנלד יעקב. ויעקב כשירד למצרים אמר (להלן מז ט) ימי שני מגורי שלשים ומאת שנה, הרי מאה ותשעים, ובמצרים היו מאתים ועשר כמנין רדו, הרי ארבע מאות שנה. ואם תאמר במצרים היו ארבע מאות, הרי קהת מיורדי מצרים היה, צא וחשוב שנותיו של קהת, ושל עמרם, ושמונים של משה שהיה כשיצאו ישראל ממצרים, אין אתה מוצא אלא שלש מאות וחמשים, ואתה צריך להוציא מהן כל השנים שחי קהת אחר לידת עמרם, ושחי עמרם אחר לידת משה: **בארץ לא להם.** לא נאמר בארץ מצרים אלא בארץ לא להם, ומשנלד יצחק (להלן כא לד) ויגר אברהם וגו' , וביצחק (שם כו ג) גור בארץ הזאת, (תהלים קה כג) ויעקב גר בארץ חם, (בראשית מז ד) לגור בארץ באנו:
@76 **וגם את הגוי.** וגם לרבות ארבע מלכיות, שאף הם כלים על ששעבדו את ישראל: **דן אנכי.** בעשר מכות: **ברכוש גדול.** בממון גדול, כמו שנאמר (שמות יב לו) וינצלו את מצרים:
@77 **ואתה תבוא.** ולא תראה כל אלה: **אל אבתיך.** אביו עובד עבודה זרה והוא מבשרו שיבא אליו, אלא למדך שעשה תרח תשובה: **תקבר בשיבה טובה.** בשרו שיעשה ישמעאל תשובה בימיו ולא יצא עשו לתרבות רעה בימיו, ולפיכך מת חמש שנים קודם זמנו ובו ביום מרד עשו:
@78 **ודור רביעי.** לאחר שיגלו למצרים יהיו שם שלשה דורות, והרביעי ישובו לארץ הזאת, לפי שבארץ כנען היה מדבר עמו וכרת ברית זו, כדכתיב (פסוק ז) לתת לך את הארץ הזאת לרשתה, וכן היה. יעקב ירד למצרים. צא וחשוב דורותיו יהודה, פרץ, חצרון, וכלב בן חצרון מבאי הארץ היה: **כי לא שלם עון האמורי.** להיות משתלח מארצו עד אותו זמן, שאין הקדוש ברוך הוא נפרע מאמה עד שתתמלא סאתה, שנאמר (ישעיה כז ח) בסאסאה בשלחה תריבנה:
@79 **ויהי השמש באה.** כמו ויהי הם מריקים שקיהם (בראשית מב לה) , ויהי הם קוברים איש, כלומר ויהי דבר זה (מ''ב יג כא) : **השמש באה.** שקעה: **ועלטה היה.** חשך היום: **והנה תנור עשן** וגו' **.** רמז לו שיפלו המלכיות בגיהנם. באה טעמו למעלה, לכך הוא מבואר שבאה כבר, ואם היה טעמו למטה באל''ף היה מבואר כשהיא שוקעת. ואי אפשר לומר כן, שהרי כבר כתיב ויהי השמש לבא, והעברת תנור עשן לאחר מכאן היתה נמצא שכבר שקעה. וזה חלוק בכל תבה לשון נקבה שיסודה שתי אותיות, כמו בא, קם, שב, כשהטעם למעלה, לשון עבר הוא, כגון זה, וכגון (להלן כט ט) ורחל באה, (שם לז ז) קמה אלמתי, (רות א טו) הנה שבה יבמתך, וכשהטעם למטה הוא לשון הוה, דבר שנעשה עכשיו והולך, כמו (להלן כט ו) באה עם הצאן, (אסתר ב יד) בערב היא באה ובבקר היא שבה:
@80 **לזרעך נתתי.** אמירתו של הקדוש ברוך הוא כאלו היא עשויה: **הנהר הגדול נהר פרת.** לפי שהוא דבוק לארץ ישראל קראהו גדול אף על פי שהוא מאוחר בארבעה נהרות היוצאים מעדן, שנאמר והנהר הרביעי הוא פרת. משל הדיוט עבד מלך מלך, הדבק לשחור וישתחוו לך:
@81 **את הקיני.** עשר אמות יש כאן ולא נתן להם אלא שבעה גוים, והשלשה אדום ומואב ועמון, והם קיני קניזי וקדמוני עתידים להיות ירשה לעתיד, שנאמר (ישעיה יא יד) אדום ומואב משלוח ידם ובני עמון משמעתם:
@82 **ואת הרפאים.** ארץ עוג, שנאמר בה (דברים ג יג) ההוא יקרא ארץ רפאים:
@84 **שפחה מצרית.** בת פרעה היתה, כשראה נסים שנעשו לשרה אמר מוטב שתהא בתי שפחה בבית זה ולא גבירה בבית אחר:
@85 **אולי אבנה ממנה.** למד על מי שאין לו בנים שאינו בנוי אלא הרוס: **אבנה ממנה.** בזכות שאכניס צרתי לתוך ביתי: **לקול שרי.** לרוח הקודש שבה:
@86 **ותקח שרי.** לקחתה בדברים אשריך שזכית לדבק בגוף קדוש כזה: **מקץ עשר שנים.** מועד הקבוע לאשה ששהתה עשר שנים ולא ילדה לבעלה חיב לשא אחרת: **לשבת אברם** וגו' **.** מגיד שאין ישיבת חוצה לארץ עולה לו מן המנין, לפי שלא נאמר לו (לעיל יב ב) ואעשך לגוי גדול, עד שיבא לארץ ישראל:
@87 **ויבא אל הגר ותהר.** מביאה ראשונה: **ותקל גברתה בעיניה.** אמרה שרי זו אין סתרה כגלויה, מראה עצמה כאלו היא צדקת ואינה צדקת, שלא זכתה להריון כל השנים הללו, ואני נתעברתי מביאה ראשונה:
@88 **חמסי עליך.** חמס העשוי לי, עליך אני מטילה הענש, כשהתפללת להקדוש ברוך הוא מה תתן לי ואנכי הולך ערירי, לא התפללת אלא עליך, והיה לך להתפלל על שנינו והייתי אני נפקדת עמך. ועוד, דבריך אתה חומס ממני שאתה שומע בזיוני ושותק: **אנכי נתתי שפחתי** וגו' **ביני וביניך.** כל ביני ובינך שבמקרא חסר, וזה מלא, קרי ביה וביניך שהכניסה עין הרע בעבורה של הגר והפילה עברה, הוא שהמלאך אומר להגר הנך הרה, והלא כבר הרתה והוא מבשר לה שתהר, אלא מלמד שהפילה הריון הראשון:
@89 **ותענה שרי.** היתה משעבדת בה בקושי:
@91 **אי מזה באת.** מהיכן באת. יודע היה, אלא לתן לה פתח לכנס עמה בדברים. ולשון אי מזה, איה המקום שתאמר עליו מזה אני באה:
@92 **ויאמר לה מלאך ה'** וגו' **.** על כל אמירה היה שלוח לה מלאך אחר, לכך נאמר מלאך בכל אמירה ואמירה:
@94 **הנך הרה.** כשתשובי תהרי, כמו (שופטים יג ז) הנך הרה, דאשת מנוח: **וילדת בן.** כמו ויולדת, ודומה לו (ירמיה כב כג) ישבת בלבנון מקננת בארזים: **וקראת שמו.** צווי הוא, כמו שאומר לזכר (יז יט) וקראת את שמו יצחק:
@95 **פרא אדם.** אוהב מדברות לצוד חיות, כמו שכתוב (כא כ. כא) ויהי רבה קשת וישב במדבר פארן: **ידו בכל.** לסטים: **ויד כל בו.** הכל שונאין אותו ומתגרין בו: **ועל פני כל אחיו ישכן.** שיהיה זרעו גדול:
@96 **אתה אל ראי.** נקוד חטף קמ''ץ מפני שהוא שם דבר, אלוה הראיה, שרואה בעלבון של עלובין: **הגם הלם.** לשון תימה, וכי סבורה הייתי שאף הלום במדברות ראיתי שלוחו של מקום אחרי רואי אותם בביתו של אברהם, ששם הייתי רגילה לראות מלאכים. ותדע שהיתה רגילה לראותם שהרי מנוח ראה את המלאך פעם אחת ואמר (שופטים יג כב) מות נמות, וזו ראתה ארבעה פעמים זה אחר זה ולא חרדה:
@97 **באר לחי ראי.** כתרגומו בירא דמלאך קיימאאתחזי עלה:
@98 **ויקרא אברם שם** וגו' **.** אף על פי שלא שמע אברם דברי המלאך שאמר (פסוק יא) וקראת שמו ישמעאל, שרתה רוח הקדש עליו וקראו ישמעאל:
@99 **ואברם בן שמנים שנה** וגו' **.** לשבחו של ישמעאל נכתב, להודיע שהיה בן שלש עשרה שנה כשנמול ולא עכב:
@100 **אני אל שדי.** אני הוא שיש די באלהותי לכל בריה, לפיכך התהלך לפני ואהיה לך לאלוה ולפטרון, וכן כל מקום שהוא במקרא פרושו די יש לו, והכל לפי הענין: **התהלך לפני.** כתרגומו פלח קדמי, הדבק בעבודתי: **והיה תמים.** אף זה צווי אחר צווי, היה שלם בכל נסיונותי. ולפי מדרשו התהלך לפני במצות מילה, ובדבר הזה תהיה תמים, שכל זמן שהערלה בך אתה בעל מום לפני. דבר אחר והיה תמים, עכשיו אתה חסר חמשה אברים שתי עינים, שתי אזנים, וראש הגויה שאוסיף לך אות על שמך ויהיו מנין אותיותיך מאתים ארבעים ושמונה כמנין אבריך:
@101 **ואתנה בריתי.** ברית של אהבה וברית הארץ להורישה לך על ידי מצוה זו:
@102 **ויפל אברם על פניו.** ממורא השכינה, שעד שלא מל לא היה בו כח לעמוד ורוח הקדש נצבת עליו, וזהו שנאמר בבלעם (במדבר כד ד) נפל וגלוי עינים. בברייתא דרבי אליעזר מצאתי כן:
@104 **כי אב המון גוים.** לשון נוטריקון של שמו. ורי''ש שהיתה בו בתחלה, שלא היה אב אלא לארם שהוא מקומו ועכשיו אב לכל העולם, לא זזה ממקומה, שאף יו''ד של שרי נתרעמה על השכינה עד שנתוספה ליהושע, שנאמר (במדבר יג טז) ויקרא משה להושע בן נון יהושע:
@105 **ונתתיך לגוים.** ישראל ואדום, שהרי ישמעאל כבר היה לו ולא היה מבשרו עליו:
@106 **והקמתי את בריתי.** ומה היא הברית, להיות לך לאלהים:
@107 **לאחזת עולם.** ושם אהיה להם לאלהים, אבל הדר בחוצה לארץ דומה כמי שאין לו אלוה:
@108 **ואתה.** וא''ו זו מוסיף על ענין ראשון אני הנה בריתי אתך, ואתה הוי זהיר לשמרו, ומה היא שמירתו, (פסוק י) זאת בריתי אשר תשמרו המול לכם וגו' :
@109 **ביני וביניכם** וגו' **.** אותם של עכשיו: **ובין זרעך אחריך.** העתידין להולד: **המול.** כמו להמול כמו שאתה אומר עשות, כמו לעשות:
@110 **ונמלתם.** כמו ומלתם והנו''ן בו יתרה ליסוד הנופל בו לפרקים, כגון נ' של נושך ונ' של נושא. ונמלתם, כמו ונשאתם, אבל ימול לשון יפעל כמו יעשה, יאכל:
@111 **יליד בית.** שילדתו השפחה בבית: **ומקנת כסף.** שקנאו משנלד:
@112 **המול ימול יליד ביתך.** כאן כפל עליו ולא אמר לשמונה ימים, ללמדך שיש יליד בית נמול לאחר שמנה ימים, כמו שמפורש במסכת שבת (דף קלח ב) :
@113 **וערל זכר.** כאן למד שהמילה באותו מקום שהוא נכר בין זכר לנקבה: **אשר לא ימול.** משיגיע לכלל ענשין ונכרתה, אבל אביו אין ענוש עליו כרת אבל עובר בעשה: **ונכרתה הנפש.** הולך ערירי ומת קודם זמנו:
@114 **לא תקרא את שמה שרי.** דמשמע שרי לי ולא לאחרים כי שרה סתם שמה, שתהא שרה על כל:
@115 **וברכתי אתה.** ומה היא הברכה, שחזרה לנערותה, שנאמר (לקמן יח יב) אחרי בלתי היתה לי עדנה: **וברכתיה.** בהנקת שדים, כשנצרכה לכך ביום משתה של יצחק, שהיו מרננים עליהם שהביאו אסופי מן השוק ואומרים בננו הוא, והביאה כל אחת בנה עמה ומניקתה לא הביאה, והיא היניקה את כלם, הוא שנאמר (כא ז) היניקה בנים שרה. בראשית רבה (נג ט) רמזו במקצת:
@116 **ויפל אברהם על פניו ויצחק.** זה תירגם אנקלוס וחדי, לשון שמחה, ושל שרה לשון מחוך. למדת שאברהם האמין ושמח, ושרה לא האמינה ולגלגה. וזהו שהקפיד הקדוש ברוך הוא על שרה ולא הקפיד על אברהם: **הלבן.** יש תמיהות שהן קימות כמו (ש''א ב כז) הנגלה נגליתי, (ש''ב טו כז) הראה אתה, אף זו היא קימת, וכך אמר בלבו הנעשה חסד זה לאחר מה שהקדוש ברוך הוא עושה לי: **ואם שרה הבת תשעים שנה.** היתה כדאי לילד. ואף על פי שדורות הראשונים היו מולידין בני חמש מאות שנה, בימי אברהם נתמעטו השנים כבר ובא תשות כח לעולם, וצא ולמד מעשרה דורות שמנח ועד אברהם שמיהרו תולדותיהן בני ששים ובני שבעים:
@117 **לו ישמעאל יחיה.** הלואי שיחיה ישמעאל, איני כדאי לקבל מתן שכר כזה: **יחיה לפניך.** יחיה ביראתך, כמו (פסוק א) התהלך לפני, פלח קדמי:
@118 **אבל.** לשון אמתת דברים, וכן (לקמן מב כא) אבל אשמים אנחנו, (מ''ב ד יד) אבל בן אין לה: **וקראת את שמו יצחק.** על שם הצחוק. ויש אומרים על שם י' נסיונות, וצ' שנה של שרה, וח' ימים שנמול, וק' שנה של אברהם. והקימתי את בריתי למה נאמר, והרי כבר כתיב (פסוק ט) ואתה את בריתי תשמור אתה וזרעך וגו' אלא לפי שאומר (פסוק ז) והקמתי וגו' , יכול בני ישמעאל ובני קטורה בכלל הקיום, תלמוד לומר והקמותי את בריתי אתו, ולא עם אחרים. ואת בריתי אקים את יצחק, למה נאמר, [אלא למד שהיה קדוש מבטן]. דבר אחר אמר ר' אבא מכאן למד קל וחומר בן הגבירה מבן האמה, כתיב (פסוק כ) כי הנה ברכתי אותו והפריתי אותו והרביתי אותו, זה ישמעאל וקל וחמר ואת בריתי אקים את יצחק: **את בריתי.** ברית המילה תהא מסורה לזרעו של יצחק:
@119 **שנים עשר נשיאם.** כעננים יכלו, כמו (משלי כה יד) נשיאים ורוח:
@121 **מעל אברהם.** לשון נקיה הוא כלפי שכינה, ולמדנו שהצדיקים מרכבתו של מקום:
@122 **בעצם היום.** בו ביום שנצטוה, ביום ולא בלילה, לא נתיירא לא מן הגוים ולא מן הלצנים, ושלא יהיו אויביו ובני דורו אומרים אלו ראינוהו לא הנחנוהו למול ולקים מצותו של מקום: **וימל.** לשון ויפעל:
@123 **בהמלו.** בהפעלו, כמו (ב ד) בהבראם:
@124 **בהמלו את בשר ערלתו.** באברהם לא נאמר את, לפי שלא היה חסר אלא חתוך בשר, שכבר נתמעך על ידי תשמיש, אבל ישמעאל שהיה ילד הוזקק לחתוך ערלה ולפרוע המילה, לכך נאמר בו את:
@125 **בעצם היום הזה.** שמלאו לאברהם תשעים ותשע שנה ולישמעאל שלש עשרה שנים נמול אברהם וישמעאל בנו:

@2 **והיה ברכ'.** הוא חסר הנושא וענניו איש ברכה וכמוהו ומאכלו בריאה.
@5 **עשו.** קנו כמו עשה את כל הכבוד הזה.
@17 **על דבר שרי.** בסבת שרי.
@21 **ולוט עמו הנגבה.** ר"ל שלוט שהיה עמו שם היה עולה ג"כ עמו. ואולם קרא המקום ההוא נגב כי ארץ מצרים היא לפאת דרום מארץ כנען. והנה הודיענו בזה המאמר שאברהם הוריד עמו לוט למצרים.
@22 **כבד מאד.** ר"ל שתנועתו כבדה מצד המקנה והכסף והזהב שהיה לו.
@23 **וילך למסעיו.** ר"ל שהלך לפי המסעות הראויות לו לרגל המלאכה אשר לפניו ולא הלך במהירו' כדי שלא ימית המקנה.
@29 **אם השמאל ואימינה.** ר"ל אם יהיו רועיך לפאת שמאל אימין רועי וירעו בפאת הימין ובזה ישלם סור המריבה מבין אברהם ולוט ומבין רועיהם. וזה שבהפרד לוט מעל אברהם סרה המריבה מבין אברהם ולוט. ועכ"ז יתכן שתהיה מריה בין רועיהם אם ירעו בצד אחד ולזה התנ' לו אברם שהוא יסיע רועיו לפאת ימין אם יבחר לוט שירעו רועיו לפאת המשאל וההפך בהפך.
@30 **כי כלה משקה.** ר"ל שהיא ארץ נחלי מים והוא שם תחת שם התאר ועניינו כלה בעלת משקה וכבר ימצאו כמו זה בלשוננו הרבה.
@31 **ויסע לוט מקדם.** ר"ל ממזרח והנה הלך למערה המקום ההוא אשר היה שם אברהם לראותו כי במערב היה כל המרעה הטוב ורצה שיהיה כל המרעה ההוא שלו והה אם היה נוטה לצפון או לדרום היה קצת המרעה ההוא לאברם ולזה אמר שהוא מפני שבחר שיהיה לו למרעה כל ככר הירדן נסע ממזרח לפאת מערב ולא נשאר לאברם כי אם במזרח שלא היה נאות למרעה.
@35 **לך אתננה.** ר"ל בדבור וזהו שהוא שנתנה לו שירשה זרעו או יהיה אמרו לך אתננה כי אברהם היה חושב שתהיה מצות ה' ית' לו במה שאמר לו אל הארץ אשר אראך שלא ישב כי אם במקום מיוחד מכנען והנה הוא המקום אשר יראהו ה' שיהיה נאות אל שידבק בו השפע האלהי ולזה כשהגיע לו שם נבואה בנה שם מזבח וחשב שיהיה רצון הש' ית' שלא יעתק מהמקום ההוא. ומפני זה שב שם בשובו ממצרים והנה הודיעו ה' יתע' כי מקומות רבים ימצאו לו נאותים בארץ ההיא והנה נתנה לו השם כלה לארכה ולרחבה לשבת באי זה מקום שיבחר כי כלה היא נבחרת ולזה בחרה ה' ית' לתתה לזרעו.
@41 **עמק השדים.** הוא עמק היו בו שדות רבות.
@41 **הוא ים המלח.** ר"ל שזה העמק היה אחר זה ים המלח כי כבר ישוב היבשה ים והים יבשה לסבות רבות כמו שהתבאר בספר האותות או יהיה המקום ההוא עמקים ים המלח ר"ל ששם יקחו מימי הים ויעשו מהם מלח.
@42 **ושלש עשרה שנה מרדו.** אפשר ששלשה עשרה שנה מרדו או שבשנה השלשה עשר מרדו ואין לנו הכרע בזה.
@43 **רפאים זוזים ואימים.** הם שמות מורים על גודל האנשים ההם וחזקם כמו שתרגם אונקלוס והנה ספר לנו זה להודיענו גבורת אלו האנשים והמלכים אשר נצח אברהם במתי מעט.
@44 **בהררם שעיר.** ר"ל בעלותם להר שעיר.
@51 **הפליט.** הוא הנמלט מן המלחמה.
@52 **חניכיו ילידי ביתו.** הם האנשים אשר גדלם בביתו מעת הלידה וחנך אותם במנהגיו החשובים כטעם חנך לנער על פי דרכו. ואפשר שיהיה הרצון בזה שכבר חנך אותם בעניין המלחמה והגבורה כי כן ראוי לבית הגדול כבית אברהם שיהיו קצת בני הבית אנשי מלחמה עם שכבר היה ראוי זה ג"כ מפני היותו רחוק ממשפחתו.
@53 **ויחלק עליהם לילה.** ר"ל שכבר נחלק בלילה ההוא הוא ועבדיו למחנות רבות כדי שיבואו עליהם מכל הצדדים ולא ימלטו איש מהם ובחר הלילה כי בזה האופן יתכן שישלם לו הנצוח.
@56 **ומלכי צדק מלך שלם.** הנה היה המנהג לקרא מלך ירושלם מלכי צדק או אדוני צדק כי הכל אחד כמו שהיה המנהג לקרא מלך מצרים פרעה. ולכן תראה ביהושע שהיה שם מלך ירושלים אדני צדק. ושלם. הוא ירושלם כטעם ויהי בשלם סוכו. ואמרו ז"ל שזה המלך היה שם בן נח ונכון הוא כי כבר נמצא בדבריו מהשלמות הרבה.
@60 **הרימותי ידי אל יי'.** הוא שבועה כמו שזכר החכם א"ע כמו כי אשא אל שמים ידי.
@63 **במחזה.** הוא כמו מראה כי הנבואה תהיה בחלום או במראה כמו שנזכר בתורה והנבואה המגעת במראה היא יותר שלמה מהנבואה אשר תגיע בחלום.
@63 **אל תירא אברם.** אולי ירא אברם שיקרא לו חטא במה שהטיב לאנשי סדום ועמורה שהיו רעים וחטאים ליי'.
@64 **ערירי.** בלא זרע.
@64 **ובן משק ביתי.** הנה משק הוא מענין ההליכה כטעם שוקק. הרצון בו מי שהנהגת עניני ביתי הוא על ידו.
@64 **דמשק.** ר"ל איש דמשק כטעם ויחזק מצרים על העם למהר לשלחם שהרצון בו אנשי מצרים.
@66 **ממעיך.** אמר זה לפי שהזרע יהיה ממות' המזון האחרון ההווה בכלי הכשול והו' הלב והכבד. וכבר נקראו האברים הפנימיים מעים בלשוננו כאמרו ותורתך בתוך מעי שהרצון בו בתוך לבי.
@68 **צדקה.** הוא מה שראוי לפי היושר והמשפט. והרצון בו שכבר האמין אברם בשם יתע' במה שיעד אותו מרבוי הזרע וחשב זה לה' יתע' ליושר המשפט כי הוא היה ראוי שישגיח ה' ית' בזה האופן מההשגחה. ואולם בענין ירושת הארץ שאל אות כי לא ידע אם יהיו בניו ראויים שישגיח בהם השם ית' בזה האופן מההשגחה.
@71 **עגלה משלשת.** פירשו רז"ל שלקח מכל מין ומין מאלו שלשה וזה דרך דרש. והנכון שצוה לקחת אלו הבהמות כשהגיעו לג' שני' כי אז הם בשלמותם לפי ענינם בעצמם. והנה אלו הבהמות הם אשר יקריבו מהם קרבן ליי' ומהעופו' התורים ובני היונה.
@72 **ויבתר אותם בתוך.** ר"ל שחלק הבהמות לחצאים כי כן היה דרך כורתי ברית שהיו חולקי' דבר אח' לחצאי' והיו עוברי' בין החלקים ההם להורות על שהם שבו כמו גוף אחד לחוזק האהבה אשר ביניהם.
@72 **איש בתרו.** ר"ל איש הבתר שבתר. והרצון בזה שהוא שם אחד מהבתרי' שבתר לקראת הבתר אשר היה זוגו כי איש ואשה בכמו זה העניין בלשוננו אמר בכרובים ופניהם איש אל אחיו וביריעות אשה אל אחותה.
@72 **והצפור לא בתר.** ר"ל התור והגוזל לוידמה שכבר שם אחד מהם בפאה האחת והאחר בפאה השנית.
@73 **העיט.** הוא העוף הדורס כטעם העיט צבוע נחלתי לי. והנה היה זה לרמז לאומות אשר יענו זרע אברם ויבלבלו הברית אשר כרת ה' עמו.
@73 **הפגרי'.** הם הבתרי' שזכר תחלה אשר בהם ישלם כריתת הברית.
@75 **ארבע מאות שנה.** ר"ל עד סוף ארבע מאו' שנה מעת הולד יעקב שהיה הראשון מהגרים מזרעו בארץ לא להם גרות מתמיד. והנה מיהר הש"י את הקץ כמו ששים שנה אם היה שלא ישבו ישראל במצרי' כי אם מאתים ועשר שנה כמו שאמרו רז"ל ואפשר שיאמר אומר שהיה מושב בני ישראל שם מאתים ושבעים שנה. וזה כי קהת אפשר שהיה כמו בן שתי שנים בבואו למצרים. ואפשר שאחר זה הזמן ק"ע שנה הוליד לו עמרם שהוא קן קהת. והנה אי אפשר שנאמ' שהיה זה הקץ מעת הולד יצחק לפי שלא ישלם לנו הקץ שזכר בפרשת וארא והוא ארבע מאות ושלשים שנה כי אי אפשר לנו שנ' שזאת הנבואה היתה קודם הולד יצחק שלשי' שנה לפי שאברה' יצא מחרן כ"ה שנה קודם הולד יצחק. וזאת הנבואה היתה להכרח אחר בא אברם לארץ כנען בעת שהתחיל אברהם להתיאש מלהיו' לו זרע ולזה אמ' ואנכי הולך ערירי. וידמה שזאת הנבואה היתה סמוך לנתינת הגר לאברהם לאשה ומה שאמר בעל סדר עולם שאחר זאת הנבואה שב אברהם לחרן ועמד שם ה' שנים כדי לכוון החשבון הנזכר בפרשת וארא הוא בלתי נראה לנו כי לא נתיאש אברם מלהיות לו זרע עד היותו בן שמני' וחמש שנה שישבו עשר שנים בארץ כנען. ולזה השתדלה אז שרה לקחת בזה עצה ממה שירא' ממנו שיהיה אמרו ואנכי הולך ערירי סביב הזמן ההוא. ועם זה לא תמצא שיצא אברהם מארץ כנען אשר צוהו השם יתע' לשבת בה אם לא לסבת חזקה כמו הרעב הכבד כי היה בזולת זה עובר מצות הש"י. ולזה לא יתכן שנאמר ששב לחרן ועמד שם חמש שנים. וג"כ הנה הכתוב ספר שכשהיו באים באר' כנען באו לחרן וישבו שם וזה לאות כי לא באו מארץ כנען לחרן ועוד שאם היה העניין כן לא מהר השם יתע' את הקץ כשהוציא ישראל ממצרים. והנראה ממה שנ' שם שכבר מהר להם את הקץ למען בריתו עם האבות. והנראה בעיני שהקץ מעת שנולד יעקב עד מלאת ת' שנה ומהר הש"י את הקץ שלשים שנה מפני חוזק העבודה הקשה אשר היו המצריים מעבידים ישראל באמרו ויאנחו בני ישראל מן העבודה ויזעקו. והנה מנין ת"ל שנה היו מעת היות לאברהם זרע. ר"ל מעת שנולד יצחק כי ביצחק נקרא לו זרע וממנו יהיה גם כן הזרע גולה בארץ לא לו. ויהיה מושב בני ישראל במצרים מאתים וארבעים שנה זה נאות מאד בזה העניין. ואפשר ג"כ שיהיה מנין ת"ל עת הגעת הנבואה הזאת לאברם שהוא לפי הנראה בלתי פחות מע"ה שנה קודם הולד יעקב. וזה שאחר זה נתנה שרה שפחתה לאברם והיה זז לאברם שמונה וחמש שנים. והנה מיהר הש"י את הקץ לפי זאת ההנחה כמו מ"ה שנים. ובעבור חטא המרגלים נתאחרו במדבר מ' שנה ונשארו ה' שנים שנכנסו לארץ קדם הקץ וזה נאות מאד כמו שנבאר בג"ה במה שיבא ר"ל שלא הגיע עדיין קץ כניסתם לארץ אחרי מות משה. ולזה היו צריכים שיהיו באופן מהשלמות שתדבק בהם ההשגחה האלהית בדרך שינצחו מאומות ההם.
@78 **ודור רביעי ישובו הנה.** ר"ל מהזרע אשר יגלה בארץ לא לו וכן היה כי קהת היה גר ודור רביעי לו היה זרע אהרן ששב לארץ כנען כמו שביאר אב"ן עזרא. ולולא חטא המרגלים היה ה' ית' ממהר את הקץ באופן שישובו שם דור שלישי שהוא משה ואהרן.
@78 **עון האמורי.** ר"ל עונש האמורי בדרך שירשו זרע אברהם ארצו.
@79 **עלטה.** חשך.
@79 **והנה תנור עשן ולפיד אש.** הוא משל לעבור כבוד ה' בין הבתרים לכרות ברית עם אברם.
@85 **אבנה.** הוא מעניין בן רצני לומר שכבר אפשר שיתהפך לה בסבתה מה שנגזר עליה מצד המערכת שלא תוליד כי היא היתה עקרה כמו שקדם.
@90 **מלאך יי'.** הוא אחד מהנביאים אשר היו בזמן ההוא כי הנביא נקרא מלאך יי' כאמרו ויבא חגי הנביא מלאך ה'. ואמרו ז"ל בב"ר שזה המלאך הוא שם.
@95 **פרא אדם.** ר"ל שהוא יהיה היותר שליט שימצא באדם דלהזיק לזולתו.
@95 **ופרא.** הוא אחת מהחיות הרעות ובזה ישלם לו שיהיה ידו בכל ר"ל שינצח הכל ובסוף העניין יהיה יד כל בו.
@95 **על פני כל אחיו ישכון.** ר"ל שתגדל ארצו עד שיהיה שוכן אצל כל אחיו והם בני קטורה.
@96 **הדובר אליה.** על ידי הנביא ולזה תרגמו אנקלוס דמתמלל עמה.
@96 **אל ראי.** ר"ל אדון הראות. והרצון בזה שהוא רואה כל הדברים ויודע אותם אין נסתר מעיניו.
@96 **הגם הלום ראיתי אחרי רואי.** ר"ל הגם פה ראיתי מה שאחרי רואי והרצון בזה שהיא תמהה כשמצאה הנביא בזה המקום כי זה מורה שכבר שלחו השם אליה להודיעה זאת הנבואה ועוד כי לא היתה חושבת שיהיה בעולם נביא זולת אברם ולזה אמרה הגם פה ראיתי מה שימשך מהפעולות בזה העולם השפל אחרי השם ית' שהוא רואה אותו ויודע כל אשר יקרה לו או יהיה הרצון בזה הגם פה ראיתי מי שהוא אחרי רואי. והרצון בו הגם פה ראיתי מי שילך אחרי השם שהוא רואי בדרך שתדבק בו הנבואה ויהיה אמרו אחרי רואי מעניין אחרי יי' ילכו. והנה אמרה זה לפי שכבר היתה תמהה מאד בראותה שם נביא.
@97 **באר לחי רואי.** ר"ל שכבר יחסה לש"י הבאר ההוא שמצאה שם הנביא שהודיעה זאת הנבואה ולזה אמרה שזה הבאר הוא למי שהוא חי וקיים תמיד שהוא רואי.
@100 **שדי.** ר"ל אשר די. והרצון שדי במציאותו להמציא הנמצאות ביותר שלם שבפנים שאפשר להם.
@100 **התהלך לפני.** ר"ל שישמור מצותי כטעם את האלהי' התהלך נח.
@100 **והיה תמים.** רמז אל המילה כי הנימול הוא תמי' שאין בו תוספת הערלה וזה שהערלה הוא דבר נוסף באד' מהכרח החומר ולזה לא תמצאה בבהמו' והנה מה שחסר המן האנושי בבריאותו מהחרה החומר השלימו הש"י באת המצוה כי כמה דברים יש בדברים הטבעיים אשר יצטרך שישלי' אותם האד' כמו העניין בעבוד' האדמ' ובמה שיכין לעצמו ומהאהל והלבוש והמזונות ולזה קרא ה' עצמו ה' אל שדי בנתינתו זאת המצוה לאבר'.
@102 **על פני כל אחיו נפל.** ומזה העניין הוא בזה המקום ור"ל שיתקיים בקיומך זרע ישמעאל עד שיהיה יחד עמך במציאות.
@116 **הלבן מאה שנה יולד.** אין הה"א ה"א התימ' אבל היא ה"א האמתתו' כדרך הנגלה נגליתי. והרצון בזה הנה לבן מאה שנה יולד ואמנ' שרה איך יתכן שתלד.
@116 **הבת תשעי' תלד.** הנה בלי ספק יהיה פלא עצום. ואולם ביארנו זה הפסוק באופן הזה ליפ שכב' מצאנו באברה' שהי' בן קל"ז שנה כשמתה שר ולקח אשה אחר זה והוליד ממנה ואין ספר שאלו לא היה ראוי אברם להוליד לא היה נושא אשה כי חלילה לו שישאנה להנאת המשגל ואיננו זר גם בזמננו זה שיולד לבן מאה שנה וכל שכן שלא היה זה זר בחק אברהם שהיה ארוך החיים ממנו וכבר הבינו זה בזה האופן בב"ר.
@117 **לפניך.** מעניין לפני ירח. והרצון בו שיתקיים עמך זרע ישמעאל עד שישאר קיים תמיד בקיומך וזה כי לפני יאמר על הדברים שהם יחד כמו ולפני אלעזר הכהן יעמוד.

@1 **ביאור דברי הספור:**
@1 **אמר** הש"י לאברהם בהיותו באור כשדים שיעזוב ארצו אשר היה שוכן בה ויפרד ממשפחתו וגם מבית אביו ללכת אל הארץ אשר יראהו וזאת הארץ אשר צוה ללכת אליה היא ארץ כנען והנה הולך עמו אביו וקצת בית אביו עד חרן כמו שספרנו בפרש' הקודמת ושם נתעכב אביו ורצה לגור שם ואברהם לכבוד אביו נתעכב שם לראות אם יוכל להעתיק אביו עמו ללכת ארצה כנען כמו שכוון מתחלת העניין לפי מה שספר ר"ל שכבר ספר שהן יצאו מאור כשדים ללכת ארצה כנען וכאשר נתבאר לאברהם שאין רצון אביו לצאת מחרן יצא הוא מחרן עם מי שרצה ללכת עמו מבית אביו והנה תרח עמד בחרן עד יום מותו ושם גם כן עמד עמו נחור וביתו לפי הנראה כי מצאנו שזרע נחור היה עומד בחרן כמו שנתבאר בתורה מלבן ובתואל. והנה צוהו ללכת ארצה כנען להיותה יותר נבחרת ויותר נכונ' שידבק לו בה השפע האלהי ויעד אותו הש' יתע' שיעשה אותו לגוי גדול לפי שהאדם בהתרחקו מאוהביו וקרוביו ועוזריו הוא מוכן מאד אל שימיתוהו האנשים ויאבד שמו ולזאת הסבה בעינה ייעד אותו שיברכהו בהצלחת קניינו ויגדל שמו עד למרחוק כי לא יאות שישלם זוז למי שילך לעיר אחרת לגור כמו שישלם לאיש בהיותו בארצו בין אנשי משפחתו ואמר לו הש"י שיהיה איש ברכה. ר"ל שיהיו פעולותיו שלמות בדרך שיהיה ראוי שתדבק בו ההשגחה האלהית ואז יגיעו לו הטוב שיעד אותו ויברך האנשים שיברכוהו ויאור מקללו ליתרון השגחת השם בו ויתברכו בו כל משפחות האדמה ר"ל שיאמרו קצתם לקצת בברכתם ישימך השם כאברה. או ירצה באמרו והיה ברכה שהשם יתע' יעד אותו שיהיה איש ברכה ר"ל כי אשר יברך מבורך וכן פי' ז"ל בב"ר וספר שכבר הלך אברם אל ארץ כנען כאשר צווה והלך עמו לוט ולא זכר לכת אביו עמו לפי שאביו לא הלך כי אם עד חרן. וזכר שאברם היה בן ע"ה שנה בצאתו מחרן ואז לקח אשתו ואת לוט בן אחיו ומקניהם והעבדים שקנו בחרן כי עבדים רבים היו לאברהם. הלא תראה במלחמת אמרפל שילידי ביתו היו שי"ח אשר היו מהם מהלכים למלחמה מלבד האחרים מיליד בית ומקנת כספו והנה עבר אברהם עד מקום שכם עד אילון מורה ושם קבע אברהם דירתו והנה היה אז הכנעני בארץ ההיא ר"ל שאז החזיק בה והוציא ממנה העם אשר היה בה והנה קרא הכנעני אחד ממשפחות כנען כי כנעני היה שם נאמר בכל על כל משפחות כנען ובפרט על משפחה מיוחדת ממנו והעד מה שאמר אחר זה והכנעני והפריזי אש יושב בארץ ולפי שהיתה הארץ ההיא ארץ כנען כמו שסופר בתורה במקומות רבי ידענו שפריזי היא משפחת מיוחדת ממנו ממשפחות כנען וזכר אחר זה שכבר נראה השם לאברהם ואמר אליו של זרעו יתן את הארץ הזאת אשר הוא רואה שמחזיק בה הכנעני. ולפי שראה אברהם שהמקום ההוא נאות להגיע בו השפע האלהי בנה שם מזבח להקריב שם לשם יתע' להגיע אליו הנבואה כמו שנתבאר בפרשת נח. וספר שאחר זה העתיק אהלו משם אל ההר ממזרח לביתאל ונטה אהלו שם באופן שהיה ביתאל למערבו והעי למזרח לראותו שהמקום ההוא יותר נאות לרדת בן השפע האלהי ולזה בנה שם מזבח לשם ית' והתפלל שם אליו להיות המקום ההוא ראוי שישלם בו הדבקו' אשר בעבורו ישמע ה' לתפילת בני האדם וספר שמסעות אברם כלם היו ללכת לפאת דרום לבחור המקום היותר נאות בארץ כנען שישלם לו בו הדבקות האלהי כי כבר ימצאו מקומות מוכנים לזה יותר מזולתם כטעם אין זה כי אם בית אלהים וראוי שתדע שה' יתע' לא צוה לאברהם שיפרד עכ"פ ממשפחתו ומבית אביו שאם היה הדבר כן היה חוטא אברה' כשנהג עמו לוט אבל היה הצווי שילך לארץ כנען להיותה יותר נבחרת לא יחוש להפרדו מאתו וממשפחתו ומבית אביו והוא מבואר לפי זאת ההנחה שאם היה יכול להניע עמו משפחתו ובית אביו להדריכם אל השלמות היה זה טוב בעיני השם:
@1 **והנה התועלת** הראשון המגיע מזה הספור הוא במדות. והוא שראוי לאדם שיקל להפרדו מארצו וממשפחתו ומבית אביו ללכת במקום שיאות לו יותר ההגעה אל שלמותו לפי של זה התכלית נברא:
@1 **התועלת** השני הוא במדות והוא שראוי לאדם שישתדל בכל עוז שיהיו אוהביו רבים ומשנאיו מעטים כי בזה ישלם הקבוץ המדיני הלא תראה שאברה השלים זה השלמות המפורסם בשייעדו השם יתע' שיברך מברכיו ויאור מקללו והנה זכר מברכיו לשון רבים להיו' אוהביו רבים ומקלליו בלשון יחיד להיותם מעטים:
@1 **התועלת** הג' הוא במדות. והוא שראוי לאדם שישתדל בשמירת הקניינים להיותם הכרחיים לאדם בשמירת גופו ולהעמדתו הלא תראה שאברהם אבינו עם שכבר הבטיחו ה' שיברכהו לא קצר מפני זה בשמירת קנייניו אבל הביאם עמו כלם והעירנו על זה באמרו שכבר הביאו עמהם כל רכושם אשר רכשו:
@1 **התועלת** הד' הוא בדעות. והוא שכבר הודיענו בזה הספור יעוד ה' ת' לאברהם שינחלו בניו את הארץ לפי שכבר נזכר בתורה במקומות רבים שכבר יעד השם לאבות שינחלו זרעם הארץ הזאת. ובזה יתישב יותר בנפשותנו אמתת זה הספור עם שבזה תועלת להודיע הסבה אשר בעבורה בחר ה' ית' שתהיה זאת הארץ לישראל והוא להיותה מוכנת מאד אל שידבק בה השפע האלהי. ולזה צוה אברהם ללכת שם וזהו אמרם ז"ל אוירא דארעא דישראל מחכים:
@10 **ויהי רעב בארץ וגומ' עד ויהי בימי אמרפל.**
@10 **ביאור דברי הספור:**
@10 **זכר** שכבר היה רעב בארץ כנען אשר היה שם אברם וירד אברם מצרימה לא להשתקע אלא לגור כי לא היה יכול אז לעמוד בארץ כנען אשר היא הארץ הנבחרת לפי שהרעב הוא כבד מאד בארץ וכאשר היה קרוב למצרים הסתכל אברהם בענייניו ובאי זה אופן תשלם לו שם ההצלה. ולזה אמר לאשתו באמת ידעתי כי אשת יפת מרא את מאד והמצרים הם היו שטופי זמה מצד המנהג ומצד הטבע. מצד המנג. כמו שאמ' כמעשה ארץ מצרים אשר ישבתם בה וגומ'. ומצד הטבע להיות הארץ חמה מאד וזה יהיה סבה שכאשר יראו אותך המצרים ואמרו אשתו זאת והרגו אותי ואותך יחיו כי הם נזהרים על אשת איש כמו שקדם כפרשת נח ובהיות העניין כן הנני מבקש ממך שתאמרי למי שישאל זה שאת אחות ובזה ייטב לי בעבורך להיותי אחיך או לכל הפחות תחי נפשי בגללך. ר"ל שלא ימיתוני והנה כבא אברם מצרימה ולוקחה שרה בית פרעה ליפיה והטיב פרעה לאברהם בעבורה לפי שכבר נאמר לו שהוא אחיה ונתן לו צאן ובקר וגו' והנה הביא הש' ית' נגעים גדולים לפרעה ולכל ביתו בסבת שרי אשת אברם ר"ל שזה המופת עשה ה' בעבור שרי מצד מה שהיא אשת אברם כי להשגחתו על אברם שמר אשתו שלא קרב אליה פרעה. ולזה הביא על פרעה ועל ביתו נגעים ימנעום מעשות זה הפעל ואולם אמרנו שהוא מנעו שלא קרב אליה ואם נזכר בתורה כמו שנזכר באבימלך באמרו ואבימלך לא קרב אליה. לפי המאמר שהוא הביא בפרעה ובביתו אלו הנגעים אחר שכבר נתעלל בה הוא בלתי ראוי. וזה כי אחר שהביא ה' אלו הנגעים להשגחתו על אבר' שישיבו לו אשתו מה זה יקצר ה' מהשגיחו על אברהם באופן שלם בדרך שתשמר אשתו מהתגאל בזמה ההיא. ואולם נזכר זה באבימלך לפי שסמוך לפעל ההוא נתעברה שרה והיה מביא זה לחשוב שיהיה עבור שרה מאבימלך ולזה ספרה התורה שאבימלך לא קרב אליה. והנה כאשר ראה פרעה זה העניין הרגיש שזה בא לו על דבר שרי אשת אברהם ושאל את פיה והגידה לו האמת ואז קרא פרעה לאברם וגנה אותו על אמרו שהיא אחותו והשיבה לו לדעתו כי היא אשתו. ומן הנראה שאברהם הגיד לו הסבה שבעבורה אמר שהיא אחותו ולזה צוה עליו פרעה אנשים לשמרו שלא יזיקוהו המצרי' לחשקם באשתו כל זמן שעמד בארץ מפני הרעב ושלחוהו ממצרים אחר כלות הרעב בארץ כנען. ואמנם עשה זה פרעה לכבוד אברהם לראותו הפלא שעשה לו ה' ית' לאהבתו בהמ שהביא עליו ועל ביתו מהנגעים. והנה עלה אברם ממצרים הוא ואשתו וכל אשר לו ולוט היה עמו שם בדרום. ואולם אמר זה לפי שארץ מצרים היתה לפאת דרום מארץ כנען והנה הלך אברם לרגל המלאכה אשר לפניו מהדרום עד בית אל עד שהגיע אל המקום הנבחר שהיה שם אהלו בתחלה בין ביתאל ובין העי אל מקום המזבח שעשה שם בראשונה וקרא שם בשם יי' כמו שקדם. או יהיה הרצון בזה שבהגיעו שם קרא שם אברם בשם יי'. וזכר אחר כן שגם ללט ההולך עם אברם היו לו צאן ובקר ואהלים ובזכות אברם נתברך. והנה רב מקניהם עד שלא יכלה הארץ להכיל אותם יחדו כי לא תספיק להם למרעה. ומפני זה היה ריב בין רועי מקנה אברם ובין רועי מקנה לוט לרצות כל אחד מהם להחזיק במרעה הטוב ובעת ההיא החזיקו הכנעני והפריזי בארץ ההיא והם שתי משפחו' ממשפחות כנען כמו שקדם ואמר אברם ללוט שאין ראוי שתהיה ביניהם מריבה ולא בין רועיהם להיותם אחים. ולפי שלא רצה אברהם להפרדה מהמקום הנבחר אשר היה בו אמר ללוט שיפרד מעליו וילך אם לצפון אם לדרום והבטיחו שבאי זה פיאה שילך יהפוך מקנהו לרעות בפיאה האחרת כדי שלא יזיקהו ר"ל שאם ילך לוט מפאת שמאל יהפוך אברם מקנהו לפאת ימים וההפך בהפך ובזה תסור המריבה מביניהם. והנה בחר לוט מארץ כנען ככר הירדן להיותו קום מאד נאות למקנה כי המקום ההוא היה רענן ודשן כגן יי' או כארץ מצרים קודם שישחתו סדום ועמורה כי אז נשחת המקום ההוא ורעננות המקום ההוא ודשנו היה מגיע עד מבא צוער ועד המקום ההוא נשחת בהשחתת סדום ועמורה. ולזה נסע לוט ממזרח מהמקום אשר היה שם אברם כדי שיהיה למקנהו כל זה המרעה הטוב. והנה נשאר אברם במקום אשר היה שם אע"פ שכבר נמנע ממקנהו הרעיה בזה הצד אשר בחרו לוט ונסתפק במרעה הצד האחר ולוט ישב בערי הככר ונטה אהלו ממקום למקום שם עד שהגיע לסדום ושם נשאר כמו שיספר אחר זה. והנה אנשי סדום היו רעים זה לזה וחטאים לש' ית'. ואולם זכר זה להגיד חסרון לוט שלא נמנע מלשכון אצלם עם היותם בזה האופן מהרוע. והנה היה סדום ועמו' מארץ כנען כמו שנזכר בפרשת נח ולפי שכבר נשאר צר המקם ההוא לאברם מפני המנע ממנו הרעיה בצד אשר ישב לוט אמר לו ה' יתע' אחרי הפרד לוט מעמו שישא עיניו ויראה מהמקום אשר הוא שם לצפון ולדרום ולמזרח ולמערב כי כל הארץ ההיא יתננה לו ולזרעו ושכבר ירבה זרעו כעפר הארם אשר לא יוכל איש למנותו ויירש הארץ ההיא. ואולם אמ' לו זה להודיע אותו שכל הארץ ההיא היא נבחרת ואם יש בה קצת מקומות יותר נבחרים מקצת ומפני זה אמר אליו הש' יתע' שיקום מהמקום ההוא אשר היה בו כי צר לו המקום ההוא וילך בארץ לארכה ולרחבה ולבקש מנוח ייטב לו כי כבר ימצאו בה מקומות רבים נאותים לו וכן עשה אברם ר"ל שהוא העתיק אהלו משם וישב באילוני ממרא אשר בחברון כי נודע לו שהמקום ההוא נאות ושם בנה מזבח ליי' להביא אליו הנבואה. וכבר תמצא שבמקום ההוא הגיע לו הנבואה באמרו וירא אליו יי' באילוני ממרא. ומהנראה שכל הנבואות הנזכרות אחר זה בזאת הפרשה הגיעו לו משם כי שם היה יושב:
@10 והנה התועלות המגיעים מזה הספור הם רבים:
@10 **התועלת** הראשון הוא במדות. והוא החריצות על בקשת ההכרחי לאד' להעמדת גופו מהמזונות וממה שידמה להם הלא תראה שאברהם עם שכבר הבטיחו ה' יתע' בהצלחת קנייניו התעורר מפני הרעב שהיה בארץ כנען ללכת לארץ מצרים ולא נמנע מההליכה שם מפני מה שצוהו ה' ית' שישב באר' כנען כי אין מצות ה' ית' כי אם להטיב לאדם לא שימות בסבתם. ולזה ידע אברהם שרצון הש"י היה שיסור משם לבקשת הטרף. ועוד שהכונה היתה בהליכת אברם לארץ כנען כדי שיהיה יות' מוכן אל שידבק בו הפשע האלהי וזה לא יתכן עם הרעב וחסרון המזונות ולזה היה יות' טוב לו שילך משם על המקום אשר ימצאו שם המזונות עד שיכלה הרעב:
@10 **התועלת** השני הוא ג"כ במדות. והוא החריצות לקחת עצה בדברים טרם הגעתם כשיסתכל האדם במה שאפשר שיקרה לו ותתישב לו העצה בזה האופן ויהיה נשמ' בזה מהרע שאיפשר שיקרה לו ואלו לא הסתכל בזה תחלה לא יתכן שיגיע לו טוב העצה לרוב המהירות אשר יצטרך לו בלקיחתה כי העצה השלמה לא תשלם אם לא יסתכל בה האדם במתון. הלא תראה שאברהם השלם השתדל לרחת עצה קודם שנכנס למצרים במה שאפשר שיקרה לו שם מהרע מצד יופי אשתו:
@10 **התועלת** הג' הוא ג"כ במדות. והוא כישיביא ההכרח שיגיע הרע לאדם ראוי שיסתכל האדם באי זה אופן יתכן שיגיע לו יותר מעט מהרע ויבחר בו ולא יתרשל מזה מפני הרע שיקרה לו כי ראוי שיהיה נבחר הרע היותר מעט לברוח מהרע היותר רב הלא תראה שאברהם בחר לרדת לארץ מצרים לברוח מהרעב אשר בארץ כנען. ואע"פ שיהיה נכון מהמקום ההוא אל שיקרה לו מהגנות שתתגאל אשתו בזאת הארץ. והנה ראוי שתדע שלא היה בזה חטא לאברם כי שרה תעשה באונס מה שתעשה מזה ולזה לא תאסר לבעלה אפילו אחר נתינת התורה כמו שאמרו ז"ל באסתר קרקע עולם היתה ואם היה אברם בוחר סבל הרעב אשר היה אפשר שימות בו על סבל מה שאפשר שיקרה לשרה מהגנות היה זה החסידות של שטות כאמרם ז"ל בג' מסוטה היכי דמי חסיד שוטה כגון דחזי דטבעה אתתא בנהרא ואמר לאו אורח ארעא לאצולה ולאיסתכולי בה:
@10 **התועלת** הרביעי הוא בדעות. והוא ללמדנו אופן השגחת ה' ית' בצדיקים עד שכבר הביא נגעי' גדולים בפרעה ובביתו לשמור אשת נביאו מהגנות ושיופי שרה אשר היה ירא אברם שיהיה כלי להמיתו שמהו הש' ית' כלי לשמירתו שם ולהצלחת קניינו עם שמרו אותה מהתגאל בטנוף וזמה. וכבר ידעת מה שהגיע מהתועלת במדות ובדעות מפני האמנה בהשגחה הזאת:
@10 **התועלת** הה' הוא במדות. והוא שראוי שישגיח האדם בהנהגת קרוביו בהשגחתו בעצמו כי בזה ישלם לאדם העזר הראוי לו ממשפחתו ולזה תראה שאברהם הוליך עמו לוט באשר הלך ובחר לו מה שבחר בעצמו:
@10 **התועלת** הששי הוא במדות. והוא החריצות לשמירת הקנינים בותר שלם שבפנים שאפשר זה הלא תראה שאברם עם היותו מובטח מה' ית' בהצלחת קניניו השתדל שיביא עמו ממצרים כל קניניו לא השאיר דבר והנהיג מקנהו במתון בדרך שלא ישיגם ההפסד ואע"פ שכבר היה חושק לשוב אל המקום הנבחר שהיה שוכן בו מארץ כנען לא נמנע מפני זה מהלך לרגל המלאכה אשר לפניו:
@10 **התועלת** השביעי הוא בדעות. והוא להודיענו אופן נפלא מאד מההשגחה האלהית. והוא שכאשר היה האדם מושגח יקרה שיהיו קרוביו ואני ביתו מושגחים בעבורו כי לאהבתו אותם יצטער אם יקרם רע וישמח בטוב אשר יקרם. ולזה יקרה מהשגחת ה' יתע' שיהיו אלו האנשים מושגחים הלא תראה שלוט מפני שהיה הולך עם אברם הצליח ה' ית' קניניו והיה לו צאן ובקר ואהלים. והנה הרחבנו המאמ' בזה האופן מההשגחה בד' מפר מלחמות השם ובביאורנו לספר איוב:
@10 **התועלת** השמיני הוא במדות. והוא שראוי להרחיק המחלוקת והמריבה כפי מה שאפשר כי בזה ישלם קבוץ הבית והמדינה הלא תראה שאברה' עם היותו משתדל בכל עוז שיהיה לוט עמו להדריכו אל הטוב כפי מה שאפשר ובעבור שיהיה לאחד מהאחר עזר הראוי לעת צורך בחר הפרד לוט מעמו להרחיק המחלוקת:
@10 **התועלת** התשיעי הוא במדות. והוא להרחיק מדת הקנאה כי בה יגיע ההפסד בקבוץ המדיני מה שלא יעלם. הלא תראה שאברם לא קנא בלוט אם יהיה לו המרעה הטוב למקנהו אבל נתן לו הבחיר' והסתפק במה שיעזבהו לוט מהמרעה עם היות לאברם כח לקחת המרעה הטוב בחזקה כי כבר התגבר על ארבעה מלכים כמו שיספר אחר זה. ועם שאברם הוא אשר הנהיגו ונהלו אל המקום שהיה בו כי זה ממה שיחייב שיהיה אברם אדון בדבר זה:
@10 **התועלת** העשירי הוא במדות. והוא שראוי שיהיה לאדם כח הסבל כי בו יוסרו הרבה מההזקין הנופלין בין בני אדם והוא שכבר הגיע מסבלנות אברם שלא כעס על לוט מפני שלא הוכיח רועיו ושנתן הבחיר' ללוט לבחור מהמרעה מה שירצה:
@10 **התועלת** האחד עשר הוא במדות. והוא שראוי שיבחר האדם המעט עם השלום מהרבה עם המריבה כטעם אמרו טוב פת חרבה ושלוה בה מבית מלא זבחי ריב. הלא תראה שאברם בחר המעט מהמרעה למקנה ועם השלום יותר מהרבה עם המריבה:
@10 **התועלת** הי"ב הוא במדות. שראוי שיסתפק האדם במה שיתכן שימצא לו ולא יבקש גדולות הלא תראה שאברהם הסתפק ברעה הנשאר למקנהו ולא היה מבקש יותר מזה לולי דבר ה' אליו שילך לבקש מנוח ייטב לו:
@10 **התועלת** הי"ג הוא במדות. והוא שראוי שירחיק האדם רוב התענוג כי הוא ממה שיביא אל בעיטה כאמרו וישמן ישורון ויבעט. הלא תראה שאנשי סדום מצד רוב התענוג שהיה להם מפני רעננות הארץ ודשנה היו רעים וחטאים ליי' מאד:
@10 **התועלת** הי"ד הוא במדות. והוא שכבר הודיענו בזה הספור שראוי להתרחק מהמריבה לפי שהמריבה היא תמנע געת השלמות לאדם בעיון עד שכבר נמנעה הנבואה לאברם בעת המריבה עד הפרד לוט מעמו וזהו מה שלמדנו באמרו וירא יי' אל אברם אחרי הפרד לוט מעמו:
@10 **התועלת** הט"ו הוא שכבר הודיענו בזה הספור יעוד רבוי זרע אברהם עד לאין מספר וקיומו ושהם יהיו יורשים את הארץ והנבחרת. וכבר נתבאר בתורה שזה הזרע הוא זרע ישראל כי ביצחק נקרא לאברהם זרע. וכבר ביאר יצחק כאשר בירך יעקב כי לזרע יעקב תהיה יורשת הארץ:
@39 **ויהי בימי אמרפל עד אחר הדברים האלה:**
@39 **ביאור דברי הספור:**
@39 **אמר** שבימי אמרפל מלך בבל. ואריוך מלך אלסר. כדר לעומר מלך עילם. ותדעל מלך גוים. עשו מלחמה אלו המלכים הנזכרים עם ברע מלך סדום. וברשע מלך עמורה. ושנאב מלך אדמה. ושמאבר מלך צכוי'. ומלך צוער בעמק השרי' ונצחום קודם זה עד שאלו המלכים החמשה עכדו כדר לעומר י"ב שנה וי"ג שנה מרדו ובי"ד שנה למרדם בא כדר לעומר והמלכים השלשה אשר אתו הכו הרפאים אשר בעשתרות קרנים והזוזים אשר בהם והאימים אשר בשוה קריתים והחורי אשר בעלותם מפניהם להר שעיר הכו עד איל פארן אשר הוא סמוך למדבר. ואחר כך שבו ובאו אל קדש והכו את כל שדה העמלקי וגם האמורי היושב בהצצון תמר. וכראות זה מלכי סדום ועמורה ואדמה וצכויים וצוער יצאו ממקומם וערכו אתם מלחמה בעמק השדים והנה נצחו ארבעה מלכים את החמשה עד שכבר נסו מפניהם מלך סדום ועמורה והפילו עצמם ברצונם בבארות חמר שהיו בעמק השידים להמלט מהם והנשארים נסו אל ההר והנה לקחו אלו הארבעה מלכים כל רכוש סדום ועמורה וכל אכלם ובין השבי אשר שבו לקחו לוט בן אחי אברם ואת רכושו כי הוא היה יושב בסדום ומפני זה הגיעתהו זה הנזק. והנה בא הנמלט מהמלחמה והגיד הענין לאברם העברי והוא היה שוכן באלוני ממרא והוא איש שהיה מזרע האמורי והוא אחי אשכול ואחי ענר והם היו בעלי ברית אברם ר"ל שכבר נקשרו עמו בקשר האהבה החזקה שהיו לעזר קצתם לקצת בעת הצורך. ולזה התעוררו אלו האנשים לצאת עם אבר' למלחמה וזה ממה שיורה על חוזק אהבתם אותו והנה כשמוע אברהם כי נשבה אחיו שם כלי המלחמה על האנשים אשר גדלו עמו בביתו והדריכם והרגילם במנהגים החשובים או בעניין המלחמה והם היו שי"ח. ורדף אחר אלו המלכים הארבעה עד דן והנה בלילה חלק מחנהו למחנות רבות כדי שיבא עליהם לילה מכל הצדדי' באופן שלא ימלט איש מהם והכה אותם ורדף אותם עד חובה אשר משמאל לדמשק והשיב כל הרכוש ואת לוט אחיו ורכושו והאנשים והעם ששבו אותם הארבעה מלכים. והנה יצא מלך סדום לקראת אברהם אל עמק שוה אחרי שובו מהכות הד' מלכים הנזכרי' ולא דבר אליו דבר עד שאכל אברהם ושתה הוא ומחנהו. והנה מלך ירושלם הוציא לאבר' ולמחנהו לחם ויין כי עייפי' היו והוא היה עובד הש"י ובירך אברם ואמר ברוך אברם לאל עליון אשר הוא קונה שמים וארץ ר"ל שהוא מושל בשמים ובארץ ומנהיג אותם והנה ברכו על אשר התעורר להלחם על אלו המלכי' החזקי' כדי להציל קרובו וברוך הש' ית' שהשגיח בך ונתן צריך בידיך וכשמוע אברם דבריו נתן לו לכבוד השם מעשר מכל השלל והשבי כטעם כל אשר תתן לי עשר אעשרנו לך כי הוא היה כהן לאל עליון. ואחר ששלמו דברי אברם עם מלך ירושלם שאל מלך סדום מאברהם שיתן לו השבי ויקח לעצמו הרכוש וענה אליו אברם הנה נשבעתי ביי' אל עליון אשר הוא קונה שמים וארץ שלא אקח מכל אשר לך דבר זולת מה שיאכלו הנערי' אשר הלכו אתי וזולת חלק ענר אשכול וממרא שהם יקחו החלק הראוי להם מהשלל והשבי ולא תאמר אני העשרתי את אברם כי יש ליי' להעשיר אותי בזולת השלל והשבי הזה. והנה התועלות המגיעים מזה ספור הם רבים:
@39 **התועלת** הראשון הוא במדות. והוא להרחיק האדם מהפעולות הרעות. הלא תראה שאנשי סדום להיותם רעים וחטאים נצחו אותם רבעה מלכים שבאו מחוץ חמשה מהם בארצם:
@39 **התועלת** השני הוא במדות. והוא שאין ראוי לאדם שיעלים עיניו מאנשי משפחתו ואע"פ שאינם מתנהגי' עמו במנהג הראוי אבל ראוי שיהיה לעזר ולהועיל להם בחזקת היד כי בזה יגיע לאדם מקרוביו העזר הראוי וישלם בזה הקבוץ המדיני הלא תראה שאברהם התגבר כנגד ארבעה מלכי' ומחניהם עם היותם גבורים מאד להציל לוט בן אחיו ורכושו ואע"פ שלא התנהג עמו לוט באופן הראוי כמו שקדם:
@39 **התועלת** השלישי הוא במדות והוא שאין ראוי ינהג האדם עמו במלחמה כי אם האנשים אשר הורגלו בתכונת הגבורה שאם יהיה ביניהם רך לבב יביא מורך בשאר לב האנשים וינוצחו ולזה לא נהג אברם עמו מאנשי ביתו כי אם האנשים אשר חנכם במנהגיו מלידה ואין ספק שעם שחנכם בשאר המדות המשובחות חנך אותם במדת הגבורה. ולזה הביאם עמו לבדם ועזב האנשים אשר היו בביתו שלא גדלו עמו מעת הלידה כי אלו כבר נשתקעו קודם היותם עמו במדות הפחותות ולאי כול להעתיקום מהם ולהגיעם אל המדות המשובחות באופן שלם או קרא חניכיו ילידי ביתו מי שחנך מהם למלחמת ואיך שיהיה הנה יצא זה התועלת מזה מספור:
@39 **התועלת** הד' הוא במדות. שאין ראוי לאדם למסור עצמו בסכנה אבל ראוי שיתגבר באופן הראוי שישלם לו בו הנצוח. ולזה תמצא שרדף אברם אחרי המלכים האלה בלילה שהיו אז יושבים בטח והיו שמחים וחוגגים על השלל שהביאו וחלק מחנהו לחלקים רבים כדי שיבואו עליהם מכל הצדדים יחד קודם שירגישו בהם וכמו אלו התחבולות הם מהתחבולות הטובות שצריך שיקחו אותם מי שיביאם ההכרח להלחם עם שתקיף ממנו:
@39 **התועלת** הה' הוא במדות. והוא שראוי לאדם לכבד השם מהונו להעיד שכל הטובות המגיעות לאדם באות מהש' ית' ולזה נתן אברם מעשר מכל השלל והשבי לכבוד הש' עם שבזה הישרה להרגיל האדם בתכונת הנדיבות והורה עם זה בזה שכבר נצח מה שנצח בעזר הש' ית' מצד יתרון ההשגחה בו:
@39 **התועלת** הששי להודיענו עוצם מעלת אברם בארץ ההיא עם היותו גר בה שכבר יצא מלך סדום לקראתו לכבדו והמתין לו לדבר עמו מעניינו עד שאכל ושתה כי זה ממה שיורה על גודל מעלת אברם אצלם ושכבר קיי' השם יתע' מה שיעדו לגדל שמו:
@39 **התועלת** הז' הוא במדות. והוא שראוי לאדם שינהיג עצמו במדת ההסתפקות ולא יבקש לו גדולו'. הלא תראה שאבר' לא רצה לקחת דבר מהשלל והשבי להסתפקו במה שחננו השם ית' מהקניינים:
@39 **התועלת** הח' הוא במדות. והוא שאין ראוי שיפזר האדם הונו ויפסיד אותו הלא תראה שאברם עם מה שהורה עניינו מתכונת הנדיבות במה שהסכי' להשיב כל הרכוש והשבי למלך סדום לא רצה לשלם משלו מה שאכלו הנערים וחלק האנשים אשר היו אתו:
@39 **התועלת** הט' הוא במדות. והוא שהאדם כשיותר משלו אין ראוי שיעשה זה באופן שיגיע היזק ממנו לזולתו כמו שיעשו קצת האנשים שיותרו משלהם להביא זולתם אל שיותרו משלהם וזה דבר בלתי ראוי הלא תראה שאברם רצה שיהיו האנשים ההולכים אתו חולקין בשלל חלק בחלק ולא רצה לותר משלהם דבר למלך סדם והוא מבואר שאם לא אמר אברם זה למלך סדום היו כושי' ענר אשכול וממרא לשאול חלקם למלך סדום אחר שאברם נתן לו חלקו שהיה העקר והשרש לעשות זאת המלחמה:
@63 **אחר הדברים האלה וגו'. עד ושרי אשת אברם וכו':**
@63 **ביאור דברי הספור:**
@63 **אמר** שאחר הדברי האלה היה דבר יי' אל אברם במראה הנבואה ואמר אליו אל תירא אברם שיקרך עון במה שהטבת לאנשי סדום ועמורה עם היותם רעים וחטאים כי אנכי מגן לך לשמרך מכל רע. ולא די שלא יגיעך עונש במה שעשית מזה אבל יהיה שכרך ממני הרבה מאד בשאעשיר אותך עושר גדול תחת מה שנתת למלך סדום לכבודי כדי שלא יאמר שהוא העשיר אותך. וכבר יורה שזה השכר הוא בקנינים כי כבר אמר אברם אל יי' על זה המאמר והנה בן ביתי יורש אותי. ועוד שאין ראוי שיבטיחהו הש' על שכר עולם הבא כי השכר ההוא הוא מחוייב שיגיע למי שראוי לו וימנע מהבלתי ראוי לו וענה אברם לש' ית' מה תתן לי מהקנינים. והנני הולך ערירי בלא בנים והממונה על ביתי הוא אליעזר שהוא מן דמשק והוא מן זרע כנען המקולל. ומפני זה לא יתכן שתגיע לי זאת הברכה בקניני' כי לא יהיה לי תועלת בה והלוקח תועלת בה הוא אליעזר שאינו ראוי לברכה. ובהיות הענין כן הנה לא יתכן שתיטב לי זאת ההטבה אשר יעדת אותי בה. ואמר עוד אברם אם היה שתטיב לי זאת ההטבה מהבצע לי בה והנה בן ביתי יורש אותי כי לא נתת לי זרע. והנה דבר יי' אליו לאמר שכבר יתן לו זרע ירשנו והוציא אותו החוצה במראה הנבואה להביט בשמי'. ואמ' אליו שכמו שלא יוכל לספור הכוכבים לרבוים כן זרעו יהיה באופן מהרבוי שלא יספרו מרוב והנה מספר הכוכבים לא היה נודע בימי אברהם. ולזה הראהו המדמה בעת הנבואה עניין רבוי הכוכבים למשל רבוי המופלג אשר ייעד אותו השם ית' שיהיה בזרעו. וכזה תמצא שראה יחזקאל בעת הנבואה שיהיה לגלגלי' קולות מצד שהיה מאמין מזה העניין כמו שזכר הרב המורה כי לא יחוייב שיהיו אצל הנביא כל הדעות האמתיות בענין סודות המציאות. והנה האמין אברם בשם יי' במה שהבטיחו מרבוי הזרע וחשב זאת ההטבה לש' ית' לצדקה ולמשפט כי הוא היה ראוי שישגיח בו הש' יתע' בזה האופן להיותו דבק בו. ואחר זה אמר אליו הש' ית' שהוא הוציאו מאור כשדים לתת לו ארץ כנען שיירשה זרעו ולפי שזה הייעוד לא יתקיים אם לא היה זרעו ראוי שישגיח בו השם יתעלה בזה האופן מההשגחה רצוני לומ' שיכלה הכנעני' מפניהם ויתן להם ארצם ירושה. שאל אברם בזה הייעוד אות. וכבר יתאר לך שלא יתקיים זה הייעוד לזרע אברם אם לא יהיו ראויים שתדבק בהם ההשגחה האלהית ממה שאמר באברם כי ידעתיו למען אשר יצוה את בניו ואת ביתו וסוף המאמר למען הביא יי' על אברהם את אשר דבר עליו. הנה כבר העירנו בזה שהשם ית' יביא על אברהם את אשר דבר עליו באמצעות הפעולות הטובות אשר יעשם זרעו ולזה שאל אברהם אות מהש"י על ירושת הארץ ואמר ה' שהו' כורת עמו ברית שיקים לו זה הייעוד ולזה צוהו במראה הנבואה שיקח עגלה ועז ואיל כל אחד מהם בני שלש שנים ותור וגוזל ולקח לו אברם את כל אלה וחלק כל אחת מהם זולת העוף לשני חצאים ונתן כל אחד מהחלקי' נכח חבירו והעוף לא בתר אבל שם התור בפאה האחת והגוזל בפאה השנית כמו שסדרה התור' בדמיון זה בעולת בהמה שיהיו מנתחים אותה לנתחיה ולא יעשו כן בעולת העוף ונדמה לאברם במראה הנבואה שכבר ירד העוף הדורס על הבתרים ההם לאכלם להשחית הברית אשר היה כורת עם השם והפריח אותם אברם מעל הבתרי' והנה בעת שהגיעה זאת הנבוא' לאברם היה השמש קרוב לשקוע ונשתקע אברם בשינה וידמה מזה שזה העניין היה ביום שהיה אחר הלילה שנלחם בה אבר' עם המלכי' ההם. וזה כי הבקר אחר הלילה ההיא אכל עם מלכי צדק והשיב אחר זה למלך סדום כל השלל והשבי ואחר זה הוכרח אבר' לישן בערב מפני שלא ישן בלילה הקודם. ולולי זה הנה לא היה העת ההו' ראוי שיישן בו אבר'. וזה מה שלמדנו מהגבלת הזמן שהגביל בעת הנבואות האלו רוצה לומר כי למחרת המלחמה היתה זאת הנבואה סמוך לשקיעת החמה או נאמ' שבסבת השתקעו בשינה אז היה התבודדות שכלו מבין שאר כחו' הנפש ונפלה עליו אימה מזה המראה שראה וחשך גדול שיראה שיוחס מה שיראה מתוך הנבואה מתוך החשך מצד רב ההעלם וההסתר אשר יקרה בהשגח אשר לו באלו הדברים הנבואיים ולרוב המונעים אשר לו מההשגה הזאת תמצא הסבה שייוחס שיראה הנביא מה שיראה מהנבואה מתך החשך ואברם לא היה יודע אל מה היה משל רדת העיט על הפגרי' ואמר לו השם יתעלה שכבר הטיב לראות במה שראהו מזה וזה שכבר יהיה זרעו גר בארץ לא להם ויעבדו בהם ויענו אותם אנשי הארץ ההיא עד סו ת' שנים מעת היות לו זרע גר בארץ לא לוגרות מתמיד וזה היה יעקב כמו שקדם כי הוא ירד למצרי' בסוף ימיו ועמד שם י"ז שנה עד שמת ואין הרצון בזה שיהיו ימי העבדו' והענוי ת' שנה אבל יתמיד העבדו' עד סוף ת' שנה מעת הולד יעקב. וכבר תמצא אמרו בספר שפטי' ותשקט הארץ שמונים שנה שאין הרצון בו שיהיו ימי ההשקט שמונים שנה אבל היה ההשקט עד סוף שמונים שנה מעת התחלת השעבוד וכמוהו ימצאו רבים בספר שפטים כמו שביארנו שם. ויעד אותו הש"י שהוא יקח נקמתו מהגוי ההוא אשר יעבודו ואחרי כן יצאו בניו ברכוש גדול מתחת הגוי ההו'. והנה היה העיט משל לזה הגוי אשר יכסוף לטרף זרעו ויחשב להפר הברית אשר בין הש"י ובין אברה' והנה הודיע אותו הש"י שיקח נקמתו מהגוי ההוא לפי שזה היה כלי להשלים ישראל באמונ' האמתית ר"ל המכו' אשר הכה הש"י המצריים כי הכה אותם באלו המכות כדי שידעו ישראל כי הוא יי' כמו שיתבאר שם בג"ה. ובזה האופן התקרבו ישראל לעבדות השי"ת והיו ראוים לירושת הארץ ויעד אותו שבחייו לא יתחיל לבוא זה הרע לזרעו ואע"פ שכבר נולד יעקב קודם מיתת אברהם ושהדור הד' מהגולי' בארץ לא להם ישובו בארץ כנען ואז יירשוה כי לא ישלם להם זה האופן מהשגח' אשר בעבור' יענש ה' האמורי ושאר משפחות כנען עד העת ההיא. והנה כששקע השמש היה חשך גדול לאברם במראה הנבוא' וראה מתוך החשך שכבר עבר בין הבתרים האלה כבוד ה' בדמיון תנור עשן שיהיה בתוכו לפיד אש. וזהו משל לכרית' הברית או ראה כבוד יי' מתוך תנור עשן ולפיד אש עובר בין הגזרים האלה כטעם וירא מלאך יי' בלבת אש. ביום ההוא כרת יי' את אברם ברית לתת לזרעו כל ארץ משפחו' כנען. וזה כי הוא הודיעו שהו' יסבב עכ"פ שיהיה זרעו ראוי להשגיח בו בזה באופן מההשגח' והנרא' שאלו העשר' משפחו היו מבני כנען כי בירושת ארץ כנען היה זה היעוד. וכבר נחלקו ז"ל בב"ר בעניין קיני וקניזי וקדמוני ואמרו שהם אדום ומואב ובני עמון ושהם יהיו לבני ישראל לימו' המשיח. והנה התועלת המגיע מזה הספור בכללו' הוא להודיע שכבר נשבע הש"י לאברה' שירשו בניו את האר' עם שכב' פרסם זה בזה הספור ובזולתו ממה שינהג מנהגו מציאו' הנבוא' אם לא יאמין בה תפול התורה בכללה. ולזה דקדק בעתות הגעת זאת הנבואה והאריך בה לישב יותר בלבב אמתת זה הספור. והנה התועלות המגיעו' מזה הספור הם רבים:
@63 **התועלת** הראשון הוא במדות. והוא שאין ראוי לשלם להטיב לרעים אבל ראוי לשנאתם ולהרחיקם מצר פעלותיהם המגונות כטעם אמרו נבזה בעיניו נמאס וזה כי בזה האופן ילמדו האנשים להתרחק מהרעים ולא ימשכו אחר פעולותיהם המגונות והנה העיר אותנו בזה במה שאמר לאברם שלא יירא כי זה ממה שיורה שכבר היה ירא שלא ישיגהו עונש על מה שעש' ולא מצאנו לו דבר יתכן שיירא ממנו זולת הטבתו לרעים ההם והם אנשי סדום:
@63 **התועלת** השני הוא במדות. והוא שראוי שישתדל האדם שיהיה לו זרע לקיים המין. הלא תראה שאברם עם היותו שלם זה האופן מהשלמות אשר היה בו היה דואג על היותו הולך ערירי:
@63 **התועלת** השלישי הוא במדות. והוא שראוי שישתדל האדם שיוריש לבניו אחריו מה שאפשר לו ולא יקנא בהם אם ישלטו בכל עמלו אחריו. הלא תראה שאברהם היה דואג מקניניו אם לא יהיה לו זרע יירשם ונתפייס כאשר הודיעו השם יתעלה שזרעו יירשנו:
@63 **התועלת** הרביעי הוא בדעות. והוא ליישב בלבנו אמונת השגחה אשר תהיה בשם יתעלה בטובים עד שיעשה השם ית' מהפלאים מצד ההשגחה יחסה אברם למשפט ולדבר ראוי וזה כי ידוע מצד התורה כי יצחק נולד לאברם על צד הפלא ואברם יחס זה הענין לשם יתעלה לצדקה והוא מבואר מצד העיון שזאת ההשגחה היא דבקה בלי ספק בטובים הראויים לה ולזה יהיה המגיע ממנה לטובים מגיע על צד המשפט והיושר:
@63 **התועלת** הה' בדעות. והוא להודיע שהייעודים הטובים אשר ייעד השם יתעלה לנביא אשר לא יתקשר בהם זמן ולא מקום לא יתקיימו אם לא יהיו האנשים ההם אשר היתה עליהם הנבואה ראויים לזה הייעוד ולזה שאל אברם אות במה שייעד לו השם שיירש זרעו הארץ:
@84 **ושרי אשת אברם עד ויהי אבר' בן תשעים שנה.**
@84 **ביאור דברי הספור:**
@84 **זכר** ששרי לא ילדה לאברם וכבר היתה לה שפחת מצרית ושמה הגר ואמרה שרי אל אברם הנה כבר עצרני ה' מלדת בא אל שפחתי אולי אזכה בסבתה שיהיה לי זרע וכמו זה העניין מצאנו ברחל שאמרה ליעקב ולא נתבארה לנו הסבה בזה וזה שאם היה זה הענין לבקש מהש"י שיתן לה זרע על צד ההשגח' הפרטית היה יותר ראוי בזה התפלה לש"י וההשתדלות שתדבק בהם ההשגחה האלהית. ומן הדומה שהכוונה היתה בזה להפך מזגה בדרך שיתכן לה ההריון וכבר יודעת שהשומן והדשנו' הוא סבה למעוט הזרע. ואם היה המנע ההריון משרה ורחל לזאת הסבה היה אפשר שיקחו תועלות בזה וזה כי הנשים שהם נשי איש אחד הם צרות זו לזו בהכרח ויקרה להן מזה צער נפלא בכאמור שפחותיהן דבר כנגדן עם שכבר יצטערו יותר ממה שיאמרו כנגדן להיותם שפחותיהן וההפעלות החזק המגיע להם מזה אולי יהיה סבה למעט השומן והדשנות אשר היה סבה המנע ההריון מהם עם שבזה תועלת להקים זרע לבעליהן אם היה שתהיינה הן בלתי ראויות להריון ולזה בחרו להן זה העניין המצער אותן על שאר הדברים שאפשר שיצטערו בו זהו מה שנראה לי עתה בזה. ואם יספק עלינו מספק ממה שאמרה שרה אחרי בלותי היתה לי עדנה שיורה שלא היה נמצא בה השומן והדשנו' אמרנו לו שזה המאמר היה ט"ו שנה אחר העניין הזה וזה כי אברהם היה בזה העת בן פ"ה שנה ואז היה בן מאה שנה והנה שמע אבר' לקול שרה להיות' עצה טובה ולקח' שרה שפחת' ונתנה לאברה' לאש' מקץ עשר שנים לשבת אבר' בארץ כנען כי אז נתבאר אליה שכבר עצרה השם מלדת והנה בא אברם אל הגר ותהר והקלה מפני זה בגבירתה עד שלא יכולה לסבל ולא רצתה שרי לענות אותה בדרך שתעתיקה מזאת התכונה הרעה אם לא ברשו' אברם ולזה ספרה לו מנהג הגר עמה ותנתרעמה על אברם מפני שלא היה מוכיח הגר שלא תנהג עם גבירתה בזה המנהג ואמ' אברם לשרי שתעשה לשפחתה כטוב בעיניה כדי שתעתיק' מזאת המדה הפחותה וענתה אותה שרי להוכיחה וברחה הגר מפניה. וכבר מצאה אחד מנביאי הדור ההוא על עין המים שהיתה בורחת. וכאשר ידע שכבר היתה בורחת מפני שרי גבירתה אמר אליה הנביא שתשוב אל גבירתה ותכנע תחת ידה ותקבל המוסר ממנה כי כונת שרי היתה לטוב לה לא לנקמה ממנה. וכבר יעדה זה הנביא שירבה השם זרעה ולא יספר מרוב ואמר אליה שהיא הרה ותלד בן ותקרא שמו ישמעאל כי שמע ה' אל עניה והשתעבדה תחת גבירתה והודיעה שזה הבן שיהיה לה יהיה זרעו מושל בכל ומנצח אותם. ובסוף הענין יהיה מנוצח והודיעה שכבר תהיה ארצו רחבה מאד שכבר ישכון אצל כל אחיו והם בני קטור' אר היה עתיד אברם להוליד ולפי ששמעה שהנביא ההוא אמר לה שישמע השם עניה והודיעה באמצעות הנביא מה שיקרה לה קראה השם הדובר אליה באמצעו' הנביא אל רואי ר"ל שהוא רואה הכל עד שכבר שלח נביאו אליה שם כי תמהה על ראותה הנביא במקום ההוא על כן קרא הקורא לבאר ההוא אשר בא אליה בו דבר הנביא אבאר לחי רואי. והנה ילדה הגר לאברהם בן וקרא שמו ישמעאל כמו שאמר אליה הנביא. וכבר היה אברם אז בן פ"ו שנה. והנה התועלות המגיעים מזה הספור הם רבים:
@84 **התועלת** הראשון הוא במדות. והוא שאין ראוי שיקצר האדם במה שיצטרך לו מהשתדלות בו בכל הסבות אשר אפשר שיהיה להם מבוא בהגעת התכלית שיכוין אליו. הלא תראה ששרי נתנה את שפחתה בחיק אברם לחשבה שאפשר שישלם לה מפני זה מה שכונה אליו והוא ההריון. והנה התועלת המגיע מזה מבואר שאם לא היה האדם משתדל בכל מה שיכוין אליו כי אם בסבות המחיבו' מציאותו היה עוזב הרבה מהדברים ההכרחיים לו או כולם. ולזה אמר הפילוסוף שצריך שיותר האדם עם נפשו באלו העניינים ולא יעמיק בהם בהעמקתו בדברים העיוניים:
@84 **התועלת** השני הוא בדעות. והוא שהאשה אשר עמדה עם אישה עשר שים ולא ילדה הוא מבואר שלא ישלם לה אם לא על המעט הריון מהאיש ההו' כי לא ימצא בין זרעו ובין זרעה האותות הצריך להמצא בין הזרעים אשר ישלם מהם ההריון. והנה העירנו בזה במה שאמר שכבר נתנה שרי שפחתה בחיק אשה מקץ עשר שנים לשבתו בארץ כנען וידמה שתהיה הסבה בזה כי מה שתעמוד האש' בין הריון להריון לא יעבור עשר שנים. וכבר ימצאו קצם מתעברות בכל שנה וקצתם משתי שנים לשתי שנים וקצתם מג' שנים לג' שנים וכן עד שיגיע לעשר שנים ולא תמצא מהן מי שתעמוד יותר מעשר שנים בין הריון להריון. וכבר ראינו אשה אחת שהיתה מתעברת אחת לשבע שנים ואחרת לחמש שנים לפי מה שסופר מהם:
@84 **התועלת** השלישי הוא במדות. והוא שאין ראוי לאשה לעשות דבר אם לא ברצון בעלה כי בזה ישלם תיקון הבית הלא תראה ששרי לא רצתה להוכיח שפחת' אם לא ברשות בעלה אברם:
@84 **התועלת** הד' הוא במדות. והוא שראוי לאדם להניח מקום לשלום הבית הלא תראה שאברם התיר לשרה שתעשה בשפחתה כטוב בעיניה עם היותה הרה ממנו ולא היה לאברם זרע אחר ואמנם עשה זה להפיס רצון שרי אשתו:
@84 **התועלת** החמישי הוא במדות. והוא שאין ראוי למקבל התוכחת שיקוץ בתוכחת מוכיחיו אבל ראוי שיקבל התוכחה מאהבה הלא תראה שכבר צוה השם יתעלה להגר שתשוב אל גבירתה ותקבל התוכחה ממנה:
@84 **התועלת** הו' להודיענו אופן השגחת השי"ת בצדיקים עד שכב' שלח נביאו להגר שהיא שפחת אברם להשיב' אל ביתו ונתפרסם זה העניין בעת מתן תורה לפי שהבאר ההוא אשר דבר אליה בו דבר השם היה נקרא מפני זה באר לחי רואי:
@84 **התועלת** השביעי להודיענו מה שיקרה בסוף הימים לזרע ישמעאל:
@100 **ויהי אברם בן תשעים שנה וגו' עד וירא אליו:**
@100 **באור דברי הספור:**
@100 **זכר** שכאשר היה אברם בן צ"ט שנה נראה השם ית' לאברם ואמר אליו אני אל שדי במציאותי להשפיע לנמצאות השלמות האפשרי להם שמור מצותי ותהיה תמים וזה יהיה כשימול בשר ערלתו כמו שיזכור אחר זה. והנני נותן בריתי ביני וביניך שאהיה לך לאלהים ולזרעך אחריך כמו שביאר אחר זה. וארבה אותך במאד מאד כזרע שיהיה לך אחר זה רצוני לומר שבמאד מזרעו ימצא המאדיות והרבוי הנפלא בהולדה. והנה נתן אברם שבח והודאה לשם יתעלה מה שייעד לו מזה ולזה נפל על פניו והשתוה לו ושם דבר השם אליו ואמר לו אני הנה בריתי אתך ותהיה לאב המון גוים. ר"ל שכבר יצאו עוד ממנו המון גוים ולזה קראו אברהם והנני מפרה אותך במאד מאד ונתתיך לגוים רבים ומלכים ממך יצאו ואולם אמר זה לפי שכבר יצאו ממנו אומות רבות כמו שיתבאר אחר זה ואין ספק שכבר היו מזרעו מלכים רבים ויהיו. ואני הנני מקים את בריתי ביני וביניך ובין זרעך אחריך לברית עולם. רוצה לומר שתמיד ארצה שיקיימו זאת המצוה באופן שיהיה זה ברית עולם שאני לך לאלהי' ולזרעך אדריך והנה יהי זה סבה שיהיה ראוי זרעך לירש כל ארץ כנען ירושת עולם ואז אהיה להם לאלהים רוצה לומר שאז אתן להם את התורה אשר ישלם בה היותי להם לאלהים כמו שנזכר בתורה במקומות רבים. והנה רצה השם שיתחנכו בזאת המצוה קודם מתן תורה להיות בני ארץ כנען שטופין בזמה והנה המילה מחלשת כח זה האבר כמו שזכר הרב המורה. וזה אצלי לשתי סבות האחת מפני הדם שישפך ממנה בסבתה. והשנית כי הכסוי הזה מוסיף חום באבר ההוא לזה תמצא שהערימה הטבע בהרבה מב"ח ששם בהם כלי ההולדה מכוסים להוסיף החום ובזה יהיו נשמרים זרע אברהם מהתגאל בזמת הארץ ויהיו מפני זה יותר נכונים לקבל התורה ולירושת הארץ. והנה ביאר השם לאברם שזה הברית אשר צוהו עליו הוא המילה רצוני לומר שימול בשר ערלתו הוא וזרעו אחריו לדורותם והיא תהיה לאות ברית ביניה' ובין השם יתעלה וצוהו שימול כל זכר מזרעו בן שמנה ימים ואפילו ילידי ביתם ומקנת כספם והם העבדים הקנויים להם שאינם מזרעם צוהו שימולו בני שמונת ימים וצוה אברם שיימול ילידי ביתו ומקנת כספו הנמצאים אתו בדרך שלא ישאר בביתו ערל אם לא היה פחות משמונת ימים ובאר לו השם יתעלה העונש שיגיע לגדול מהמחוייבים להמול אם לא ימול והוא הכרת נפשו ואבדה לפי שכבר הפר ברית השם והראה מפני זה שאין השם יתעלה לו לאלהים כי המילה היתה לאות ברית שהשם יתעלה הוא לאלהים למקיימים זאת המצוה כמו שקדם. והנה אמר השם יתעלה אל אברהם שלא תרא עוד אשתו שרי כי שרה שמה ויעד אברהם שכבר יהיו לו ממנה גוים ומלכי עמים ממנה יהיו והנה נשתנה שם אברם ואשתו להפך מזלם לפי מה שאמרו רז"ל בב"ר אמרו אברם אינו מוליד אברהם מוליד שרי אינה יולדת שרה יולדת. ולזה אמרו ששנוי השם מהפך גזר דינו של אדם והנה יש לזה המאמר פנים מההראו' אין מכא בזכירתם בזה המקום ואפשר ששנה השם ית' שמם להורות על היותם כמו בריאה חדשה להכנסתם אז בבריתו ית' שיהיה להם ולזרעם אחריהם לאלהים ולזה קורא להם שם חדש והנה כששמע אברהם זה הייעוד הודה לשם יתעלה ושמח ואמר בלבו הנה לבן מאה שנה יולד ואולם שרה היתכן שתלד והיא בת צ' שנה הנה יהיה זה פלא עצום מהש יתעלה ולזה אמר אברהם אל אלהים שכבר יספיק לו אם יתקיים לו מישמעאל זרע ולא יבקש אליו הגדולות האלו. ואמר אליו השם יתעלה שכבר יהיה לו זרע משרה והיא תקרא שמו יצחק להורות על רוב השמחה שתהיה להם בעבורו וממנו יהיה הזרע הנבחר. ולישמעאל גם כן שמעתי תפלתך שיתקיי' לך ממנו זרע ויפרה וירבה במאד מאד ויוליד י"ב בנים ותהיה מעלתם גדולה אצל אנשי הארץ אשר יהיו בה עד שיעשו אותם נשיאים עליהם ובריתו אשר כרת עם אברהם להיות לו לאלהים ולזרעו אחריו יקים בבני יצחק אשר תלד שרה למועד הזה בשנה האחרת כי מזרעו יהיה הזרע הנבחר אשר יהיה השם יתעלה לו לאלהים והנה כאשר השלי' הש' יתעלה לדבר עם אברהם ונסתלקה שכינתו מעליו קיים אברהם מצות השם להמול בשר ערלתו ונמול עמו ישמעאל בנו וילידי ביתו ומקנת כספו ולא אחר לעשות הדבר אבל עשה זה ביום עצמו שבאהו מצות השם יתעלה והנה התועלות המגיעות מזה הספור הם רבים:
@100 **התועלת** הא' הוא במדות. והו' שכאשר ירצה האדם שיגיע אוהבו לעשות דבר להועיל לו אשר בו אצלו מהזרו' והצער הנה ראוי שיפליג להזכיר לו תחלה התועלו' הנמשכו' מזה הפועל קודם שיזכור הפועל אשר יצוהו עליו. והנה בזה האופן יעלים ממנו החשק אשר לו להשיג אותם התועלות הזרות והצער אשר בפועל ההיא וזאת ההתחלה טובה מאד להגיע בה האדם אל הדברים המועילים לו אשר הם בלתי ערבים. ולזה תמצא שכבר הפליג השם יתעלה לזכור לאברהם התועלות המגיעות לו מפני הברית אשר הוא כורת עמו קודם שיגיד לו מה הוא עניין זה הברית לפי שיש בזה הפועל מהזרות והצער מה שלאי עלם וכ"ש שיהיה בזה מהצער הנפלא לאברהם להיותו זקן בהמולו בשר ערלתו:
@100 **התועלת** הב' הוא במדות. והוא שראוי לאדם שישגיח בבני ביתו ומשרתיו וידריכם בהנהגה הישרה לפי שתיקון הנהגתם הוא בידו להיותם תחתיו ולזה תמצא שנצטוה אברהם שימול הוא וזרעו ילידי ביתם ומקנת כספם:
@100 **התועלת** הג' הוא במדות. והוא שראוי שיבוש האדם מרבוי הטובות אשר ייטב לו אוהבו וירחיק מלקבל אותם הטובות בדרך שלא ירא' עצמו חושק לקבל ההטבות ההם כי בזה מהתועלת לקיים האהבה אשר בין האוהבים וזה שלא יעלם ולזה תמצא שאברהם להיותו מוטבע בזאת התכונה הטובה אמר לשם יתעלה כאשר יעד אותו שכבר תלד לו שרה בן ויהיה לו ממנה גוים ומלכ' עמים שכבר יספיק לו אם יתקיים לו זרע מישמעאל ואינו מבקש מהשם יתעלה כמו אלו הגדולות להורות על בושתו מההטבות שהטיב לו השם יתעלה:
@100 **התועלת** הד' הוא בעניינים התוריים והוא שראוי לאדם שיזרז עצמו לעשות המצו' ולא יתעצל מעשייתם ואף על פי שיקרה לו מעשייתם צער מה אם היתה שם מצוה בזה התואר. הלא תראה שאברהם אבינו קיים זאת המצוה ביום בעינו אשר באתהו מצות השם עליה. ואל זה המספר הרב מן האנשים אשר היו בבית ובה היום בעינו אשר לא יתכן שישלם לו זה כי אם בעשותו זה הפועל בזריזות נפלא. והתועלת המגיע מזה הברית אשר כרת השם עם אברהם כבר זכרנוהו עם ביאור דברי הספור הזה. ואולם הסבה אשר בעבורה צוה השם יתעלה שיהיה הנולד נמול לשמונה ימים. והשלמת המאמר בזאת המצוה יהיה בג"ה בפרשת אשה כי תזריע. והנה האריך בכאן בזה המאמר עד שכבר נזכרו בו שלש עשרה בריתות כמו שאמרו רז"ל להורות על מעלת זאת המצוה ליישב יות' בנפשותינו אמתת זה הספור אשר נשאר רשומו בעת מתן תורה וזה כי זרע יעקב היו נמולים כאמרו לא נוכל לתת את אחותינו לאיש אשר לו ערלה. ומפני זה היה תועלת עצום בז הספור לפרסם עניין הנבואה אשר ההאמנה בה היא פנת התורה:
